// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"critical-points":{"id":"critical-points","prerequisites":["derivative-power-rules","chain-rule","quotient-rule"],"next":["increasing-decreasing"],"related":["domain-range","first-derivative-test","extreme-value-theorem"],"objectives":["分清楚局部極值與絕對極值。","找出一個函數所有的臨界點：$f'=0$ 的點，以及 $f'$ 不存在的點，而且都要在定義域裡面。","在閉區間上用「臨界點＋端點」比大小，求絕對最大值與最小值。"],"concept":[{"heading":"① 山頂與谷底","body":["$f$ 在 $c$ 有局部極大值（也叫相對極大值），意思是：在 $c$ 附近的一小段裡，$f(c)$ 最大。局部極小值同理。兩者合稱局部極值。","絕對最大值是整個考慮範圍裡最大的那個值。局部極大只跟「附近」比，所以一個函數可以有好幾個局部極大，而且不一定是絕對最大。"]},{"heading":"② 光滑的山頂，切線是水平的","body":["在山頂，往左看是上坡、往右看是下坡；如果那裡有切線，它只能是水平的，也就是 $f'(c)=0$。這叫 Fermat 定理：$f$ 在定義域內部的點 $c$ 有局部極值，而且 $f'(c)$ 存在，那 $f'(c)=0$。","但山頂也可能是尖的。$f(x)=|x|$ 在 $0$ 有極小值，那裡沒有切線，$f'(0)$ 不存在。"]},{"heading":"Fermat 定理的證明","body":["設 $f$ 在 $c$ 有局部極大，而且 $f'(c)$ 存在。在 $c$ 附近，$f(c+h)-f(c)\\le 0$。","$h>0$ 時，$\\frac{f(c+h)-f(c)}{h}\\le 0$，所以右極限 $f'(c)\\le 0$；$h<0$ 時，分母是負的，$\\frac{f(c+h)-f(c)}{h}\\ge 0$，所以左極限 $f'(c)\\ge 0$。","$f'(c)$ 存在，左右極限相等，只能是 $0$。局部極小的情形把不等號反過來，論證一樣。"],"collapsible":true},{"heading":"③ 臨界點的定義","body":["$c$ 是 $f$ 的臨界點，意思是：$c$ 在 $f$ 的定義域內部，而且 $f'(c)=0$ 或 $f'(c)$ 不存在。","由 ②，內部的局部極值只會發生在臨界點。所以找極值的第一步，是把臨界點全部列出來。","臨界點只是候選人。$f(x)=x^3$ 的 $f'(0)=0$，但 $x^3$ 在 $0$ 只是平一下又繼續往上，不是極值。要判斷是不是極值，看〈一階導數判別〉。"]},{"heading":"④ 閉區間上的最大最小","body":["$f$ 在閉區間 $[a,b]$ 上連續，就一定有絕對最大值與最小值（〈極值定理〉）。它們不是出現在內部，就是出現在端點；在內部的話一定是臨界點。","所以做法是：列出 $(a,b)$ 內的臨界點，連同 $a$、$b$ 一起代進 $f$，最大的就是最大值，最小的就是最小值。不用判斷誰是山頂。"]}],"workedExamples":[{"title":"閉區間：臨界點＋端點","prompt":"求 $f(x)=x^3-3x^2-9x+5$ 在 $[-2,4]$ 上的絕對最大值與最小值。","problemId":"lec-04-q1a","steps":["$f'(x)=3x^2-6x-9=3(x^2-2x-3)=3(x-3)(x+1)$。多項式的導數處處存在，臨界點只有 $f'=0$ 的 $x=-1$、$x=3$，兩個都在 $(-2,4)$ 裡。","四個候選點代進 $f$：$f(-2)=-8-12+18+5=3$；$f(-1)=-1-3+9+5=10$；$f(3)=27-27-27+5=-22$；$f(4)=64-48-36+5=-15$。","最大的是 $10$（在 $x=-1$），最小的是 $-22$（在 $x=3$）。"],"answer":"最大值 $10$，最小值 $-22$"},{"title":"$f'$ 不存在的臨界點","prompt":"求 $g(x)=x^{2/3}(5-x)$ 在 $[-1,5]$ 上的絕對最大值。","problemId":"lec-04-q1b","steps":["乘法法則：$g'(x)=\\frac{2}{3}x^{-1/3}(5-x)-x^{2/3}$。提出 $\\frac{1}{3}x^{-1/3}$：$g'(x)=\\frac{1}{3}x^{-1/3}(2(5-x)-3x)=\\frac{10-5x}{3x^{1/3}}$。","$g'=0$：$10-5x=0$，$x=2$。$g'$ 不存在：分母 $x^{1/3}=0$，$x=0$。$g$ 在 $x=0$ 有定義（$g(0)=0$），而 $0$ 在區間內部，所以 $0$ 也是臨界點。","代值：$g(-1)=(-1)^{2/3}\\cdot 6=1\\cdot 6=6$（$(-1)^{2/3}=((-1)^{1/3})^2=(-1)^2=1$）；$g(0)=0$；$g(2)=2^{2/3}\\cdot 3\\approx 4.76$；$g(5)=0$。","最大值是 $6$，出現在端點 $x=-1$。"],"answer":"$6$","note":"只解 $g'=0$ 會漏掉 $x=0$。這題的最小值 $0$ 就出現在 $x=0$ 與 $x=5$。"},{"title":"先看定義域","prompt":"求 $f(x)=\\ln x-x$ 的所有臨界點。","problemId":"si-set-015","steps":["定義域是 $x>0$。","$f'(x)=\\frac{1}{x}-1=\\frac{1-x}{x}$。$f'=0$ 得 $x=1$。","$f'$ 在 $x=0$ 不存在，但 $0$ 不在定義域裡，所以不是臨界點。","臨界點只有 $x=1$。"],"answer":"$x=1$"}],"pitfalls":["只解 $f'=0$，漏掉 $f'$ 不存在的點（尖角、垂直切線）。","把定義域外的點也算成臨界點，例如 $\\ln x-x$ 的 $x=0$。","以為臨界點一定是極值：$x^3$ 在 $0$ 就不是。","閉區間題忘了把端點代進去比。"],"voice":"51e620cb","sections":[{"title":"山頂與谷底","beats":[{"show":["局部極大：$c$ 附近 $f(c)$ 最大"],"note":"也叫相對極大值；局部極小同理。","say":"f 在 c 有局部極大，意思是只看 c 附近的一小段，f 在 c 的值最大。谷底就是局部極小。","t":[0,9024]},{"show":["絕對最大：整個範圍裡最大"],"say":"絕對最大值，是拿整個考慮範圍來比。局部極大只跟鄰居比。","t":[9024,15936]},{"show":["局部極大可以有好幾個"],"note":"不一定是絕對最大。","say":"所以一條曲線可以有好幾座山頂，高度不一樣，最高的那座也不一定就是絕對最大。","t":[15936,23760]}],"check":3},{"title":"山頂的切線","beats":[{"show":["光滑的山頂：$f'(c)=0$"],"note":"左邊上坡、右邊下坡，切線只能是水平的。","say":"站在光滑的山頂，往左是上坡、往右是下坡。那裡如果有切線，只能是水平的，斜率零。","t":[23760,33528]},{"show":["Fermat 定理"],"note":"內部的局部極值，$f'(c)$ 存在 ⇒ $f'(c)=0$。","say":"這叫 Fermat 定理：定義域內部的局部極值，只要導數存在，導數就是零。證明在下一節。","t":[33528,42480]},{"show":["$f(x)=|x|$ 在 $0$：尖的谷底"],"note":"有極小值，但 $f'(0)$ 不存在。","say":"可是山頂也可能是尖的。絕對值 x 在零有極小值，那裡卻沒有切線。","t":[42480,50016]}],"predict":{"ask":"$f(x)=|x|$ 在 $x=0$ 有極小值。$f'(0)$ 是？","options":[{"label":"不存在","correct":true},{"label":"$0$","why":"你直接套了 Fermat 定理，但它要先有「$f'(c)$ 存在」。$|x|$ 在 $0$ 是尖角，沒有切線。"},{"label":"$1$","why":"$1$ 只是右邊的斜率；左邊的斜率不一樣，所以導數不存在。"}]}},{"title":"證明：左右夾出 $0$","proof":true,"of":2,"skeleton":"直接","beats":[{"show":["看差商的正負號，左右夾出 $0$"],"note":"設 $c$ 是局部極大，$f'(c)$ 存在。","say":"策略：在山頂附近，往哪邊走都不會更高。看差商的正負號，左右兩邊把導數夾成零。","t":[50016,59400]},{"show":["$c$ 附近：$f(c+h)-f(c)\\le0$"],"say":"c 是局部極大，所以 c 附近的值都不超過 f 在 c 的值，分子小於等於零。","t":[59400,66480]},{"show":["$h>0$：差商 $\\le0$ ⇒ 右極限 $\\le0$"],"say":"往右走，h 是正的，分子不大於零，差商小於等於零，右極限也小於等於零。","t":[66480,74304]},{"show":["$h<0$：差商 $\\ge0$ ⇒ 左極限 $\\ge0$"],"note":"分子 $\\le0$，分母 $h<0$。","why":{"ask":"為什麼這一邊差商 $\\ge0$？","say":"往左走，差商為什麼變成大於等於零？","options":[{"label":"分子 $\\le0$，分母 $h<0$","correct":true},{"label":"左邊的函數值比 $f(c)$ 大","why":"反了：$c$ 是局部極大，左邊的值也 $\\le f(c)$；變號是因為分母 $h<0$。"},{"label":"$f'(c)\\ge0$ 是假設","why":"假設只說 $f'(c)$ 存在，沒說正負；正負號是從局部極大推出來的。"}],"t":[74304,78480]},"say":"分子還是不大於零，可是往左走 h 是負的，負的除以負的，差商大於等於零。","t":[78480,86016]},{"show":["左右極限都是 $f'(c)$ ⇒ $f'(c)=0$"],"note":"一個 $\\le0$、一個 $\\ge0$，只能是 $0$。","why":{"ask":"為什麼只能是 $0$？","say":"一邊不大於零，一邊不小於零。為什麼 f prime c 只能是零？","options":[{"label":"$f'(c)$ 存在，左右極限都等於它","correct":true},{"label":"$c$ 是山頂，切線一定水平","why":"那是要證的結論，不能拿來當理由；尖的山頂就沒有切線。"},{"label":"差商在 $h=0$ 等於 $0$","why":"差商在 $h=0$ 沒有定義；用的是左右極限都等於 $f'(c)$。"}],"t":[86016,92400]},"say":"導數存在，左右極限就相等，都是 f prime c。它不大於零也不小於零，只能是零。極小同理。","t":[92400,103080]}],"where":{"ask":"「$f'(c)$ 存在」用在哪一步？","steps":[{"label":"$c$ 附近 $f(c+h)-f(c)\\le0$","why":"這只用到 $c$ 是局部極大。"},{"label":"$h>0$ 時差商 $\\le0$","why":"這只看正負號：分子 $\\le0$、分母 $>0$。"},{"label":"$h<0$ 時差商 $\\ge0$","why":"這也只看正負號：分子 $\\le0$、分母 $<0$。"},{"label":"左右極限相等，所以 $f'(c)=0$","correct":true}]}},{"title":"臨界點","beats":[{"show":["$c$ 在定義域內部","$f'(c)=0$ 或 $f'(c)$ 不存在"],"say":"臨界點有兩個條件：c 在定義域內部，而且 f prime 在 c 等於零，或是根本不存在。","t":[103080,110976]},{"show":["$f(x)=\\ln x-x$"],"note":"定義域是 $x>0$。","say":"例子：自然對數 x 減 x。先看定義域，x 要大於零。","t":[110976,117528]},{"show":["$f'(x)=\\frac{1-x}{x}$"],"note":"$f'=0$ 得 $x=1$。","say":"微分得 x 分之一減一，通分是 x 分之一減 x。等於零的地方是 x 等於一。","t":[117528,125376]},{"show":["$x=0$：$f'$ 不存在，但不算"],"note":"$0$ 不在定義域裡。","say":"f prime 在零也不存在，可是零不在定義域裡，不是臨界點。所以臨界點只有一。","t":[125376,133776]}],"check":0},{"title":"只是候選人","beats":[{"show":["內部的局部極值 ⇒ 臨界點"],"note":"找極值的第一步：列出所有臨界點。","say":"內部的極值只會發生在臨界點，所以找極值的第一步，就是把臨界點全部列出來。","t":[133776,141576]},{"show":["$f(x)=x^3$：$f'(0)=0$"],"note":"平一下又繼續往上，不是極值。","say":"但反過來不對。x 三次方在零的導數是零，曲線只是平一下，又繼續往上爬。","t":[141576,150168]},{"show":["是不是極值，另外判斷"],"note":"見〈一階導數判別〉。","say":"臨界點只是候選人。誰才是真的山頂谷底，要用一階導數判別來看。","t":[150168,157656]}],"check":1},{"title":"閉區間：比一比","beats":[{"show":["連續在 $[a,b]$ ⇒ 有最大、最小"],"note":"不在內部的臨界點，就在端點。","say":"f 在閉區間上連續，一定有絕對最大和最小。它們不是在內部的臨界點，就是在端點。","t":[157656,166536]},{"show":["臨界點＋端點，全部代進 $f$"],"note":"最大的就是最大值，不用判斷誰是山頂。","say":"所以做法很機械：臨界點連同兩個端點全部代進去，比大小就好。","t":[166536,173352]},{"show":["$f=x^3-3x^2-9x+5$，$[-2,4]$"],"note":"$f'=3(x-3)(x+1)$，臨界點 $-1$、$3$。","say":"例如 x 三次方減三 x 平方減九 x 加五，在負二到四。導數分解後，臨界點是負一和三。","t":[173352,183072]},{"show":["$f(-2)=3$，$f(-1)=10$","$f(3)=-22$，$f(4)=-15$"],"say":"四個候選點代進去：三、十、負二十二、負十五。最大值十，最小值負二十二。","t":[183072,192624]}],"check":2},{"title":"別漏了尖點","beats":[{"show":["$g(x)=x^{2/3}(5-x)$，$[-1,5]$"],"say":"再一題：x 的三分之二次方乘五減 x，區間負一到五。","t":[192624,198432]},{"show":["$g'(x)=\\frac{10-5x}{3x^{1/3}}$"],"note":"乘法法則，再提出 $\\frac{1}{3}x^{-1/3}$。","say":"用乘法法則微分，整理成三倍 x 的三分之一次方分之十減五 x。","t":[198432,204816]},{"show":["$g'=0$：$x=2$","$g'$ 不存在：$x=0$"],"note":"$g(0)=0$ 有定義，$0$ 在內部。","say":"分子是零得 x 等於二；分母是零得 x 等於零。g 在零有定義，零也是臨界點。","t":[204816,213264]},{"show":["$g(-1)=6$，$g(0)=0$","$g(2)\\approx 4.76$，$g(5)=0$"],"say":"四個點代進去：六、零、大約四點七六、零。","t":[213264,218640]}],"predict":{"ask":"$g$ 在 $[-1,5]$ 上的最大值出現在哪裡？","options":[{"label":"$x=-1$，最大值 $6$","correct":true},{"label":"$x=2$","why":"$x=2$ 是 $g'=0$ 的點，但 $g(2)\\approx 4.76$ 比端點 $g(-1)=6$ 小；端點也要比。"},{"label":"$x=0$","why":"$g(0)=0$ 是最小值，不是最大值。"}]}}],"checks":[{"ask":"$f(x)=|x-2|$ 的臨界點是？","options":[{"label":"$x=2$，因為 $f'(2)$ 不存在","correct":true},{"label":"沒有，因為 $f'$ 從來不等於 $0$","why":"你只找了 $f'=0$。$f'$ 不存在的點也算臨界點，$|x-2|$ 在 $2$ 是尖角。"},{"label":"$x=0$","why":"$x=0$ 是 $|x|$ 的尖角；這裡平移了，尖角在 $x=2$。"}]},{"ask":"$f(x)=x^3$ 在 $x=0$：","options":[{"label":"是臨界點，但不是極值","correct":true},{"label":"是臨界點，所以是極值","why":"臨界點只是候選人。$x^3$ 在 $0$ 左邊比 $0$ 小、右邊比 $0$ 大，不是極大也不是極小。"},{"label":"不是臨界點","why":"$f'(x)=3x^2$，$f'(0)=0$，而且 $0$ 在定義域內部，符合臨界點的定義。"}]},{"ask":"$f(x)=x^3-3x$ 在 $[0,2]$ 上的最大值是？","options":[{"label":"$2$","correct":true},{"label":"$-2$","why":"$-2$ 是臨界點 $x=1$ 的值，那是最小值；還要把端點代進去：$f(0)=0$、$f(2)=2$。"},{"label":"$0$","why":"你可能只比了 $f(0)$ 與 $f(1)$。右端點 $f(2)=8-6=2$ 比較大。"}]},{"ask":"局部極大值與絕對最大值的關係？","options":[{"label":"局部極大只跟附近比，不一定是絕對最大","correct":true},{"label":"局部極大一定就是絕對最大","why":"一個函數可以有好幾個局部極大，高度各不相同；而且絕對最大也可能出現在端點。"},{"label":"絕對最大一定是局部極大","why":"絕對最大可能出現在閉區間的端點，例如 $x^3-3x$ 在 $[0,2]$ 的最大值在 $x=2$；端點不在定義域內部，不算局部極大。"}]}],"practice":[{"id":"lec-04-m1","core":true},{"id":"si-set-002","core":true},{"id":"si-set-015","core":true},{"id":"db-ext-001","core":true},{"id":"lec-04-q1a","core":true},{"id":"si-set-014","core":true},{"id":"lec-04-q1b","core":true},{"id":"si-set-013"},{"id":"si-set-016"},{"id":"db-ext-002"},{"id":"db-ext-003"},{"id":"db-ext-004","challenge":true,"note":"挑戰：$\\sin x+\\cos x$ 的臨界點要解 $\\tan x=1$，記得只取 $[0,\\pi]$ 裡的那一個。"}]},"increasing-decreasing":{"id":"increasing-decreasing","prerequisites":["critical-points","intermediate-value-theorem"],"next":["first-derivative-test"],"related":["mean-value-theorem"],"objectives":["用 $f'$ 的正負判斷 $f$ 在哪些區間遞增、哪些區間遞減。","會畫 $f'$ 的符號表：找出切點、每段取一個測試點或看因式的正負。","定義域斷開的地方要分段寫，不能把兩段併成一段。"],"concept":[{"heading":"① 遞增、遞減是什麼","body":["$f$ 在區間 $I$ 上遞增：$I$ 裡任取 $x_1<x_2$，都有 $f(x_1)<f(x_2)$。往右走，高度一直變高。遞減就是一直變低。","這是在講一整段區間，不是講一個點。例如 $x^2$ 在 $(-\\infty,0)$ 上遞減、在 $(0,\\infty)$ 上遞增；答案永遠寫成區間，而不是一個個的點。"]},{"heading":"② 斜率是正的，就是上坡","body":["$f'(x)$ 是切線斜率。如果在一整段區間上 $f'>0$，每一點都往上斜，$f$ 在那段遞增；$f'<0$ 則遞減。","反過來不完全成立：$x^3$ 在整條數線上遞增，但 $f'(0)=0$。遞增的函數，導數可以在個別點等於 $0$。"]},{"heading":"為什麼 $f'>0$ 推得出遞增（用均值定理）","body":["設 $f$ 在區間 $I$ 上可微，而且 $I$ 上處處 $f'>0$。任取 $I$ 裡的 $x_1<x_2$。$f$ 在 $[x_1,x_2]$ 上可微，所以也連續，符合〈均值定理〉的條件：存在 $c\\in(x_1,x_2)$ 使 $f(x_2)-f(x_1)=f'(c)(x_2-x_1)$。","右邊 $f'(c)>0$、$x_2-x_1>0$，所以 $f(x_2)-f(x_1)>0$。$x_1$、$x_2$ 是任取的，所以 $f$ 在 $I$ 上遞增。$f'<0$ 的情形同理。"],"collapsible":true},{"heading":"③ 符號表：先找切點，再一段一段看","body":["$f'$ 只會在兩種地方換號：$f'=0$ 或 $f'$ 不存在的點（包括不在定義域的點）。在兩個切點之間，只要 $f'$ 連續而且沒有零點，由〈中間值定理〉它就不會換號。本課的函數 $f'$ 在定義域上都連續。","所以步驟是：寫出定義域 → 求 $f'$ 並因式分解 → 找出所有切點、把數線切開 → 每一段看 $f'$ 的正負（代一個測試點，或數負的因式有幾個）→ 正的那段遞增、負的那段遞減。"]},{"heading":"④ 斷開的地方要分開寫","body":["$f(x)=\\frac{x^2}{x-1}$ 在 $(0,1)$ 與 $(1,2)$ 上都遞減，但不能說它在 $(0,1)\\cup(1,2)$ 上遞減：$f(0.5)=-0.5$，$f(1.5)=4.5$，右邊的值反而比較大。中間 $x=1$ 斷開了，兩段要分開寫。"]}],"workedExamples":[{"title":"多項式","prompt":"求 $f(x)=x^3-3x$ 的遞增、遞減區間。","problemId":"si-int-005","steps":["定義域是全體實數。$f'(x)=3x^2-3=3(x-1)(x+1)$。","切點：$x=-1$、$x=1$，把數線切成三段。","$x<-1$：$x-1<0$、$x+1<0$，兩個負因式相乘為正，$f'>0$。$-1<x<1$：只有 $x-1$ 為負，$f'<0$。$x>1$：兩個都正，$f'>0$。","遞增：$(-\\infty,-1)$ 與 $(1,\\infty)$；遞減：$(-1,1)$。"],"answer":"遞增 $(-\\infty,-1)$、$(1,\\infty)$；遞減 $(-1,1)$"},{"title":"有一個永遠為正的因式","prompt":"求 $f(x)=xe^{-x}$ 的遞增、遞減區間。","problemId":"lec-04-m5","steps":["乘法法則與連鎖律：$f'(x)=e^{-x}+x\\cdot(-e^{-x})=(1-x)e^{-x}$。","$e^{-x}$ 對所有 $x$ 都大於 $0$，不影響正負；$f'$ 的正負跟 $1-x$ 一樣。","$x<1$ 時 $1-x>0$，$f'>0$；$x>1$ 時 $f'<0$。","遞增：$(-\\infty,1)$；遞減：$(1,\\infty)$。"],"answer":"遞增 $(-\\infty,1)$；遞減 $(1,\\infty)$"},{"title":"定義域斷開","prompt":"求 $f(x)=\\frac{x^2}{x-1}$ 的遞增、遞減區間。","problemId":"lec-04-q3c","steps":["定義域：$x\\ne 1$。","除法法則：$f'(x)=\\frac{2x(x-1)-x^2\\cdot 1}{(x-1)^2}=\\frac{x^2-2x}{(x-1)^2}=\\frac{x(x-2)}{(x-1)^2}$。","切點：$f'=0$ 的 $x=0$、$x=2$，以及不在定義域的 $x=1$。數線切成四段。","分母 $(x-1)^2$ 在 $x\\ne 1$ 時恆正，正負看 $x(x-2)$：$x<0$ 為正；$0<x<1$ 與 $1<x<2$ 為負；$x>2$ 為正。","遞增：$(-\\infty,0)$、$(2,\\infty)$；遞減：$(0,1)$、$(1,2)$，這兩段要分開寫。"],"answer":"遞增 $(-\\infty,0)$、$(2,\\infty)$；遞減 $(0,1)$、$(1,2)$"}],"pitfalls":["只找 $f'=0$ 的點，漏了定義域斷開的點。","把斷開的兩段寫成一段遞減（$\\frac{x^2}{x-1}$ 的 $(0,1)$ 與 $(1,2)$）。","把恆正的因式（$e^{-x}$、平方）也拿來切數線，或因此搞錯正負。","以為遞增就要處處 $f'>0$：$x^3$ 在 $0$ 的導數是 $0$，照樣遞增。"],"voice":"680e36cd","sections":[{"title":"遞增是什麼","beats":[{"show":["$x_1<x_2$ ⇒ $f(x_1)<f(x_2)$"],"note":"在區間 $I$ 裡任取兩點都成立。","say":"f 在一段區間上遞增，意思是在裡面任取兩點，右邊那一點的函數值一定比較大。","t":[0,7632]},{"show":["往右走，一直變高"],"note":"遞減就是一直變低。","say":"看圖就是往右走，高度一路往上；遞減則是一路往下。","t":[7632,13392]},{"show":["講的是一整段，不是一個點"],"note":"答案永遠寫成區間。","say":"這是在講一整段區間。像 x 平方，左半邊往下、右半邊往上，答案要寫成區間。","t":[13392,22296]}],"predict":{"ask":"$x^2$ 在哪裡遞增？","options":[{"label":"$(0,\\infty)$","correct":true},{"label":"$(-\\infty,0)$","why":"在 $x<0$ 那段往右走，$x^2$ 越來越小，那是遞減。"},{"label":"$x=0$","why":"$0$ 是谷底那一個點；遞增講的是一整段區間，不是一個點。"}]}},{"title":"斜率正就是上坡","beats":[{"show":["整段 $f'>0$ ⇒ $f$ 遞增","整段 $f'<0$ ⇒ $f$ 遞減"],"say":"f prime 是切線斜率。一整段上每一點都往上斜，f 在那段就遞增；都往下斜就遞減。","t":[22296,31104]},{"show":["反過來不完全成立"],"note":"$x^3$ 處處遞增，但 $f'(0)=0$。","say":"反過來不一定：x 三次方在整條數線上遞增，可是在零的導數是零。","t":[31104,37920]},{"show":["證明靠均值定理"],"note":"完整證明在全文。","say":"為什麼斜率是正的，右邊就比較高？要用均值定理，把兩點的差寫成某一點的斜率乘距離。","t":[37920,47328]}],"check":3},{"title":"符號表","beats":[{"show":["$f'$ 只在切點換號"],"note":"$f'=0$、$f'$ 不存在、不在定義域的點。","say":"f prime 只會在兩種地方換號：等於零，或不存在的地方，包括不在定義域的點。","t":[47328,54960]},{"show":["定義域 → 因式分解 $f'$ → 切數線 → 看正負"],"say":"步驟：寫定義域，把 f prime 因式分解，用切點把數線切開，再一段一段看正負。","t":[54960,62976]},{"show":["$f(x)=x^3-3x$"],"note":"$f'(x)=3(x-1)(x+1)$，切點 $-1$、$1$。","say":"例如 x 三次方減三 x。導數是三倍的 x 減一乘 x 加一，切點負一和一，數線切成三段。","t":[62976,72480]},{"show":["$x<-1$：$+$，$-1<x<1$：$-$，$x>1$：$+$"],"note":"數負的因式有幾個。","say":"最左邊兩個因式都是負的，乘起來是正；中間只有一個負的，是負；最右邊都是正。","t":[72480,80880]},{"show":["遞增 $(-\\infty,-1)$、$(1,\\infty)$","遞減 $(-1,1)$"],"say":"正的那兩段遞增，負的那段遞減。","t":[80880,84624]}],"check":1},{"title":"恆正的因式","beats":[{"show":["$f(x)=xe^{-x}$"],"note":"$f'(x)=(1-x)e^{-x}$","say":"x 乘 e 的負 x 次方。用乘法法則和連鎖律，導數整理成一減 x，乘 e 的負 x 次方。","t":[84624,93552]},{"show":["$e^{-x}>0$，不影響正負"],"note":"$f'$ 的正負跟 $1-x$ 一樣。","say":"e 的負 x 次方永遠是正的，不用拿來切數線；正負只看一減 x。","t":[93552,99960]},{"show":["遞增 $(-\\infty,1)$","遞減 $(1,\\infty)$"],"say":"x 小於一時一減 x 是正的，遞增；x 大於一就遞減。","t":[99960,105408]}],"check":0},{"title":"斷開要分開寫","beats":[{"show":["$f(x)=\\frac{x^2}{x-1}$，$x\\ne 1$"],"say":"最後一題，x 平方除以 x 減一。先看定義域：x 不能是一。","t":[105408,112704]},{"show":["$f'(x)=\\frac{x(x-2)}{(x-1)^2}$"],"note":"切點：$0$、$2$，還有不在定義域的 $1$。","say":"除法法則算完，分子是 x 乘 x 減二。切點是零、二，還有斷開的一，一起把數線切開。","t":[112704,122448]},{"show":["分母恆正，看 $x(x-2)$"],"note":"$(0,1)$、$(1,2)$ 都是負的。","say":"分母是平方，恆正，正負只看分子：兩邊是正的，零到二之間扣掉一，都是負的。","t":[122448,131160]},{"show":["遞減：$(0,1)$、$(1,2)$ 分開寫"],"note":"$f(0.5)=-0.5$，$f(1.5)=4.5$。","say":"這兩段不能併成一段：零點五的值是負零點五，一點五的值是四點五，右邊反而比較大。","t":[131160,139464]}],"check":2}],"checks":[{"ask":"$f'(x)=(x-2)e^{x}$。$f$ 在哪裡遞增？","options":[{"label":"$(2,\\infty)$","correct":true},{"label":"$(-\\infty,2)$","why":"$x<2$ 時 $x-2<0$，而 $e^x>0$，$f'$ 是負的，那是遞減。"},{"label":"全體實數","why":"$e^x$ 恆正，但 $x-2$ 會變號；正負要看 $x-2$。"}]},{"ask":"$f'(x)=x(x-3)$。在 $(0,3)$ 上 $f'$ 的正負與 $f$ 的走向？","options":[{"label":"$f'<0$，$f$ 遞減","correct":true},{"label":"$f'>0$，$f$ 遞增","why":"代測試點 $x=1$：$1\\cdot(-2)=-2<0$。$0$ 與 $3$ 之間只有 $x-3$ 是負的。"},{"label":"無法判斷","why":"$f'$ 是多項式、連續，在 $0$ 與 $3$ 之間沒有零點，所以整段同號，代一點就知道。"}]},{"ask":"$f(x)=\\frac{1}{x}$ 在 $(-\\infty,0)$ 與 $(0,\\infty)$ 都遞減。可以說 $f$ 在 $(-\\infty,0)\\cup(0,\\infty)$ 上遞減嗎？","options":[{"label":"不行，$f(-1)=-1<f(1)=1$","correct":true},{"label":"可以，兩段都遞減，合起來也遞減","why":"遞減要求任取 $x_1<x_2$ 都有 $f(x_1)>f(x_2)$。$x_1=-1$、$x_2=1$ 就不成立。"},{"label":"可以，因為 $f'=-\\frac{1}{x^2}$ 處處是負的","why":"$f'$ 只在定義域上是負的；$x=0$ 斷開，均值定理不能跨過去用。"}]},{"ask":"$f'>0$ 推出 $f$ 遞增，這件事的證明用到哪個定理？","options":[{"label":"均值定理","correct":true},{"label":"中間值定理","why":"中間值定理用在判斷 $f'$ 在兩個切點之間不換號；把「斜率為正」變成「右邊比較高」靠的是均值定理。"},{"label":"Fermat 定理","why":"Fermat 定理講的是極值點的導數為 $0$，跟遞增無關。"}]}],"practice":[{"id":"si-int-005","core":true},{"id":"si-int-016","core":true},{"id":"lec-04-m5","core":true},{"id":"si-int-017","core":true},{"id":"si-int-018","core":true},{"id":"lec-04-q3c","core":true},{"id":"si-int-019"},{"id":"si-int-020"},{"id":"si-int-021","challenge":true,"note":"挑戰：$f'=1-2\\cos x$，要在 $(0,2\\pi)$ 裡解 $\\cos x=\\frac{1}{2}$，再看兩段之間的正負。"},{"id":"px-mvt-002","challenge":true,"note":"挑戰：寫出 $f'>0\\Rightarrow$ 遞增的證明，就是本課可折疊的那一段。"}]},"first-derivative-test":{"id":"first-derivative-test","prerequisites":["critical-points","increasing-decreasing"],"next":["second-derivative"],"related":["mean-value-theorem","second-derivative-test"],"objectives":["在每個臨界點看 $f'$ 左右的正負，判斷是局部極大、局部極小，還是都不是。","看出偶次方因式不會讓 $f'$ 換號，所以那裡不是極值。","只給 $f'$ 的式子或圖形，也能判斷 $f$ 的極值位置。"],"concept":[{"heading":"① 先下坡再上坡，中間就是谷底","body":["〈增減區間〉告訴我們 $f'$ 的正負就是上坡下坡。設 $c$ 是臨界點、$f$ 在 $c$ 連續：","$f'$ 在 $c$ 的左邊正、右邊負：先上坡再下坡，$f(c)$ 是局部極大。","$f'$ 在 $c$ 的左邊負、右邊正：先下坡再上坡，$f(c)$ 是局部極小。","$f'$ 在 $c$ 的兩邊同號：一路上坡（或一路下坡），$c$ 不是極值。"]},{"heading":"② $f'(c)$ 不存在也能用","body":["判別只看 $c$ 左右兩側的 $f'$，不需要 $f'(c)$ 本身。$f(x)=|x|$ 在 $0$ 沒有導數，但左邊 $f'=-1$、右邊 $f'=1$，所以 $0$ 是局部極小。條件是 $f$ 在 $c$ 要連續；在 $c$ 跳開的函數，左右的坡度說明不了 $f(c)$ 本身的高度。"]},{"heading":"③ 偶次方的因式不換號","body":["$f'$ 因式分解之後，看每個因式在切點兩側有沒有換號。$(x-3)$ 這種一次因式過了 $x=3$ 會換號；$(x-1)^2$、$x^4$ 這種偶次方因式恆不為負，過了零點不換號。","所以 $f'(x)=(x+2)(x-1)^2$ 在 $x=1$ 兩邊同號，$x=1$ 是臨界點但不是極值；在 $x=-2$ 換號，那裡才是極值。"]},{"heading":"④ 完整步驟","body":["求 $f'$ 並因式分解 → 列出臨界點 → 畫 $f'$ 的符號表（跟〈增減區間〉一樣）→ 每個臨界點讀左右的正負：正變負是極大、負變正是極小、不變不是極值 → 把是極值的點代回 $f$，求出極值本身。","最後一步常被忘記：題目問「局部極大值」，要的是 $f(c)$ 這個高度；問「在哪裡」，要的才是 $c$。"]},{"heading":"為什麼左正右負就是局部極大","body":["設 $f$ 在 $c$ 連續，在 $(c-\\delta,c)$ 與 $(c,c+\\delta)$ 上可微，而且前一段 $f'>0$、後一段 $f'<0$。","任取 $x\\in(c-\\delta,c)$。$f$ 在 $[x,c]$ 上連續（右端點用的是「$f$ 在 $c$ 連續」）、在 $(x,c)$ 上可微，由〈均值定理〉有 $\\xi\\in(x,c)$ 使 $f(c)-f(x)=f'(\\xi)(c-x)$。$f'(\\xi)>0$、$c-x>0$，所以 $f(x)<f(c)$。","任取 $x\\in(c,c+\\delta)$，同樣有 $\\xi\\in(c,x)$ 使 $f(x)-f(c)=f'(\\xi)(x-c)<0$，所以 $f(x)<f(c)$。","$c$ 附近每一點都比 $f(c)$ 低，$f(c)$ 是局部極大。另外兩種情形把不等號換掉，論證一樣。"],"collapsible":true}],"workedExamples":[{"title":"有一個臨界點不是極值","prompt":"$f(x)=x^4-4x^3$。找出所有局部極值。","problemId":"db-ext-012","steps":["$f'(x)=4x^3-12x^2=4x^2(x-3)$。臨界點：$x=0$、$x=3$。","$4x^2$ 恆 $\\ge 0$，只在 $0$ 等於 $0$，不換號；正負看 $x-3$。","$x<0$：$f'<0$。$0<x<3$：$f'<0$。$x>3$：$f'>0$。","$x=0$ 兩邊都是負，不是極值。$x=3$ 由負變正，是局部極小，$f(3)=81-108=-27$。"],"answer":"只有局部極小 $f(3)=-27$；$x=0$ 不是極值"},{"title":"只給 $f'$","prompt":"某函數的導函數是 $f'(x)=(x+2)(x-1)^2$。$f$ 的局部極值在哪裡？","problemId":"lec-04-q4a","steps":["臨界點：$x=-2$、$x=1$（多項式 $f'$ 處處存在）。","$(x-1)^2$ 恆 $\\ge 0$，正負看 $x+2$。","$x<-2$：$f'<0$。$-2<x<1$：$f'>0$。$x>1$：$f'>0$。","$x=-2$ 由負變正，是局部極小。$x=1$ 兩邊都正，不是極值。"],"answer":"$x=-2$ 是局部極小；$x=1$ 不是極值"},{"title":"三角函數","prompt":"$f(x)=x-2\\sin x$，$0<x<2\\pi$。找出局部極值。","steps":["$f'(x)=1-2\\cos x$。$f'=0$：$\\cos x=\\frac{1}{2}$，在 $(0,2\\pi)$ 裡是 $x=\\frac{\\pi}{3}$、$x=\\frac{5\\pi}{3}$。","$0<x<\\frac{\\pi}{3}$：$\\cos x>\\frac{1}{2}$，$f'<0$。$\\frac{\\pi}{3}<x<\\frac{5\\pi}{3}$：$\\cos x<\\frac{1}{2}$，$f'>0$。$\\frac{5\\pi}{3}<x<2\\pi$：$\\cos x>\\frac{1}{2}$，$f'<0$。","$x=\\frac{\\pi}{3}$ 由負變正，局部極小 $f(\\frac{\\pi}{3})=\\frac{\\pi}{3}-2\\cdot\\frac{\\sqrt{3}}{2}=\\frac{\\pi}{3}-\\sqrt{3}\\approx -0.685$。","$x=\\frac{5\\pi}{3}$ 由正變負，局部極大 $f(\\frac{5\\pi}{3})=\\frac{5\\pi}{3}-2\\cdot\\left(-\\frac{\\sqrt{3}}{2}\\right)=\\frac{5\\pi}{3}+\\sqrt{3}\\approx 6.968$。"],"answer":"局部極小 $\\frac{\\pi}{3}-\\sqrt{3}$（$x=\\frac{\\pi}{3}$）；局部極大 $\\frac{5\\pi}{3}+\\sqrt{3}$（$x=\\frac{5\\pi}{3}$）"}],"pitfalls":["看到臨界點就宣布是極值，沒有檢查 $f'$ 有沒有換號。","把偶次方因式 $(x-1)^2$ 也當成會換號。","左右弄反：先正後負是極大（上坡再下坡），不是極小。","題目給的是 $f'$ 的圖，卻去找 $f'$ 的山頂；$f$ 的極值看的是 $f'$ 穿過 $x$ 軸的地方。"],"voice":"c7832f32","sections":[{"title":"上坡下坡","beats":[{"show":["$c$ 是臨界點、$f$ 在 $c$ 連續"],"note":"看 $f'$ 在 $c$ 左右的正負。","say":"f prime 的正負就是上坡下坡。拿一個臨界點 c，只要看它左邊和右邊的 f prime。","t":[0,8016]},{"show":["左正右負：局部極大"],"note":"先上坡再下坡。","say":"左邊是正、右邊是負：先爬上去再走下來，c 就是山頂，局部極大。","t":[8016,15312]},{"show":["左負右正：局部極小"],"note":"先下坡再上坡。","say":"左邊負、右邊正：先走下去再爬上來，c 是谷底，局部極小。","t":[15312,22080]},{"show":["兩邊同號：不是極值"],"say":"兩邊同號，就是一路上坡或一路下坡，c 只是經過，不是極值。","t":[22080,28872]}],"check":0},{"title":"沒有導數也能用","beats":[{"show":["只看 $c$ 兩側，不用 $f'(c)$"],"say":"這個判別只看 c 的左右兩側，根本用不到 f prime 在 c 的值。","t":[28872,34608]},{"show":["$f(x)=|x|$ 在 $0$"],"note":"左邊 $f'=-1$、右邊 $f'=1$：局部極小。","say":"絕對值 x 在零沒有導數，可是左邊斜率負一、右邊斜率一，先下後上，零是局部極小。","t":[34608,43320]},{"show":["條件：$f$ 在 $c$ 連續"],"note":"跳開的函數，坡度說明不了 $f(c)$ 的高度。","say":"但 f 在 c 要連續。如果在 c 跳開，左右的坡度就管不到 c 那一點有多高。","t":[43320,50952]}],"check":3},{"title":"偶次方不換號","beats":[{"show":["$(x-3)$：過了 $3$ 換號","$(x-1)^2$：恆不為負，不換號"],"say":"因式分解之後，一次的因式過了零點會換號；平方這種偶次方，過了零點還是不為負，不換號。","t":[50952,60240]},{"show":["$f'(x)=(x+2)(x-1)^2$"],"note":"正負只看 $x+2$。","say":"例如 f prime 是 x 加二，乘 x 減一的平方。平方那一項不管，正負只看 x 加二。","t":[60240,68616]},{"show":["$x=-2$：由負變正，局部極小"],"say":"在負二，f prime 由負變正，那裡是局部極小。","t":[68616,73584]},{"show":["$x=1$：兩邊都正，不是極值"],"note":"是臨界點，但不是極值。","say":"在一，兩邊都是正的，f 一路上坡。一是臨界點，卻不是極值。","t":[73584,81192]}],"check":1},{"title":"完整走一次","beats":[{"show":["$f'$ 分解 → 臨界點 → 符號表 → 判讀 → 代回 $f$"],"say":"完整步驟：分解 f prime，列臨界點，畫符號表，讀左右正負，最後把極值點代回 f。","t":[81192,89808]},{"show":["$f(x)=x^4-4x^3$"],"note":"$f'(x)=4x^2(x-3)$，臨界點 $0$、$3$。","say":"例如 x 四次方減四 x 三次方。導數是四 x 平方乘 x 減三，臨界點是零和三。","t":[89808,98448]},{"show":["$x<0$：$-$，$0<x<3$：$-$，$x>3$：$+$"],"note":"$4x^2$ 不換號，看 $x-3$。","say":"四 x 平方不換號，正負看 x 減三：三的左邊都是負的，右邊是正的。","t":[98448,105792]},{"show":["$x=0$：不是極值","$x=3$：局部極小"],"say":"零的兩邊都是負，不是極值；三由負變正，是局部極小。","t":[105792,111960]}],"predict":{"ask":"題目問「局部極小值」，答案是？","options":[{"label":"$f(3)=-27$","correct":true},{"label":"$3$","why":"$3$ 是極小發生的位置；問「值」要的是高度，代回 $f$：$81-108=-27$。"},{"label":"$f(0)=0$","why":"$x=0$ 兩邊 $f'$ 都是負的，沒換號，不是極值。"}]}},{"title":"三角函數","beats":[{"show":["$f(x)=x-2\\sin x$，$0<x<2\\pi$"],"note":"$f'(x)=1-2\\cos x$","say":"x 減二 sine x，x 在零到二 pi 之間。導數是一減二 cosine x。","t":[111960,118872]},{"show":["$\\cos x=\\frac{1}{2}$：$x=\\frac{\\pi}{3}$、$\\frac{5\\pi}{3}$"],"say":"令它等於零，cosine x 等於二分之一，在這個範圍裡是三分之 pi 和三分之五 pi。","t":[118872,126696]},{"show":["$-$、$+$、$-$"],"note":"$\\cos x>\\frac{1}{2}$ 時 $f'<0$。","say":"cosine x 大於二分之一的兩頭，f prime 是負的；中間那段是正的。","t":[126696,133104]},{"show":["$x=\\frac{\\pi}{3}$：極小 $\\approx -0.685$","$x=\\frac{5\\pi}{3}$：極大 $\\approx 6.968$"],"say":"三分之 pi 由負變正是極小，大約負零點六八五；三分之五 pi 由正變負是極大，大約六點九六八。","t":[133104,142560]},{"show":["只給 $f'$ 的圖也一樣"],"note":"看 $f'$ 穿過 $x$ 軸的地方，不是 $f'$ 的山頂。","say":"如果題目給的是 f prime 的圖，就看它穿過 x 軸的地方，跟 f prime 自己的山頂無關。","t":[142560,149928]}],"check":2}],"checks":[{"ask":"$f'$ 在 $x=2$ 左邊為負、右邊為正，$f$ 在 $2$ 連續。$x=2$ 是？","options":[{"label":"局部極小","correct":true},{"label":"局部極大","why":"左負右正是先下坡再上坡，那是谷底。先上再下才是山頂。"},{"label":"不是極值","why":"$f'$ 有換號就是極值；兩邊同號才不是。"}]},{"ask":"$f'(x)=x^2(x-2)$。$x=0$ 是？","options":[{"label":"不是極值","correct":true},{"label":"局部極大","why":"$x^2$ 在 $0$ 兩側都是正的，正負只看 $x-2$，在 $0$ 兩側都是負，$f'$ 沒換號。"},{"label":"局部極小","why":"$x=0$ 附近 $f'$ 都是負的，$f$ 一路下坡；真正的局部極小在 $x=2$。"}]},{"ask":"圖上是 $f'$ 的圖形（不是 $f$）。$f$ 的局部極大出現在哪？","options":[{"label":"$f'$ 的圖由上往下穿過 $x$ 軸的地方","correct":true},{"label":"$f'$ 的圖的最高點","why":"那是 $f'$ 最大、$f$ 爬得最快的地方，不是 $f$ 的山頂。$f$ 的山頂要 $f'$ 由正變負。"},{"label":"$f'$ 的圖由下往上穿過 $x$ 軸的地方","why":"由下往上是 $f'$ 由負變正，那是 $f$ 的局部極小。"}]},{"ask":"$f(x)=|x|$ 在 $0$ 沒有導數。$0$ 是不是 $f$ 的局部極值？","options":[{"label":"是局部極小，因為左邊 $f'=-1$、右邊 $f'=1$","correct":true},{"label":"不能判斷，因為 $f'(0)$ 不存在","why":"一階導數判別只看 $c$ 的左右兩側，不需要 $f'(c)$；需要的是 $f$ 在 $0$ 連續，$|x|$ 是連續的。"},{"label":"不是，因為只有 $f'=0$ 的點才可能是極值","why":"$f'$ 不存在的點也是臨界點，尖角常常就是極值。"}]}],"practice":[{"id":"gx-001","core":true},{"id":"gx-002","core":true},{"id":"lec-04-q4a","core":true},{"id":"lec-04-q4b","core":true},{"id":"gi-004","core":true},{"id":"gx-006","core":true},{"id":"gx-004"},{"id":"gx-003"},{"id":"gx-007"},{"id":"gx-009"},{"id":"gx-010"},{"id":"db-ext-012","challenge":true,"note":"挑戰：$x=0$ 也是臨界點，但 $4x^2$ 不換號。"},{"id":"gx-008","challenge":true,"note":"挑戰：$f'=x^2(x-2)$ 在 $0$ 碰到 $x$ 軸卻沒有穿過去。"}]},"second-derivative":{"id":"second-derivative","prerequisites":["higher-derivatives","increasing-decreasing"],"next":["concavity"],"related":["first-derivative-test"],"objectives":["說出 $f''$ 在問什麼：$f'$（斜率）變化得多快。","用 $f''$ 的正負判斷 $f'$ 在哪裡遞增、哪裡遞減。","在直線運動裡由位置求速度、加速度，並判斷速率在變大還是變小。"],"concept":[{"heading":"① $f''$ 量的是「斜率怎麼變」","body":["$f'(x)$ 是切線斜率。把 $f'$ 當成一個新的函數，再微分一次，得到 $f''(x)$：斜率每往右一單位，變化多少。","最熟悉的例子是運動。位置 $s(t)$ 微分是速度 $v(t)=s'(t)$，再微分是加速度 $a(t)=s''(t)$。加速度不是「跑多快」，是「速度變化得多快」。"]},{"heading":"② $f''$ 的正負 → $f'$ 的增減","body":["把〈增減區間〉用在 $f'$ 身上：$f''>0$ 的區間，$f'$ 遞增；$f''<0$ 的區間，$f'$ 遞減。","$f'$ 遞增的意思是切線越來越往上翹：斜率從 $-2$、$-1$、$0$、$1$、$2$ 一路變大，曲線像碗一樣往上彎。這就是下一課〈凹向上／凹向下〉的內容。","讀圖的版本：$f''$ 是 $f'$ 圖形的斜率。$f'$ 的圖往上走的地方，$f''>0$。"]},{"heading":"③ 加速與減速：看 $v$ 和 $a$ 是否同號","body":["「加速」在日常用語裡指速率 $|v|$ 變大，跟 $a$ 的正負不是同一件事。$v=-5$ 而 $a=-2$：速度往負方向越來越大，速率在變大。","規則：在一段時間裡 $v$ 與 $a$ 同號，速率增加；異號，速率減少。原因是 $(v^2)'=2va$。$va>0$ 時 $v^2$ 遞增，速率 $|v|=\\sqrt{v^2}$ 也跟著遞增；$va<0$ 時則遞減。"]},{"heading":"④ 記號，以及 $f''$ 可能不存在","body":["$f''(x)$、$y''$、$\\frac{d^2y}{dx^2}$ 都是同一個東西。$\\frac{d^2y}{dx^2}$ 的寫法來自把 $\\frac{d}{dx}$ 作用兩次：$\\frac{d}{dx}\\left(\\frac{dy}{dx}\\right)$。","$f'$ 存在，不保證 $f''$ 存在。$f(x)=x|x|$ 的導函數是 $f'(x)=2|x|$，在 $0$ 有尖角，所以 $f''(0)$ 不存在。之後找 $f''$ 換號的點時，這種點也要列進去。"]}],"workedExamples":[{"title":"算 $f''$，看 $f'$ 的增減","prompt":"$f(x)=xe^x$。求 $f''$，並說出 $f'$ 在哪裡遞增。","problemId":"der-029","steps":["乘法法則：$f'(x)=e^x+xe^x=(x+1)e^x$。","再用一次乘法法則：$f''(x)=e^x+(x+1)e^x=(x+2)e^x$。","$e^x$ 恆正，$f''$ 的正負跟 $x+2$ 一樣：$x>-2$ 時 $f''>0$。","所以 $f'$ 在 $(-2,\\infty)$ 上遞增，在 $(-\\infty,-2)$ 上遞減。"],"answer":"$f''(x)=(x+2)e^x$；$f'$ 在 $(-2,\\infty)$ 遞增"},{"title":"直線運動：何時在加速","prompt":"質點位置 $s(t)=t^3-6t^2+9t$（$t\\ge 0$）。求 $a(4)$，以及速率增加的時段。","problemId":"lec-02-q4d","steps":["$v(t)=3t^2-12t+9=3(t-1)(t-3)$；$a(t)=6t-12=6(t-2)$。$a(4)=24-12=12$。","$v$ 在 $t=1$、$3$ 換號；$a$ 在 $t=2$ 換號。把 $t\\ge 0$ 切成四段看符號：","$(0,1)$：$v>0$、$a<0$，異號，減速。$(1,2)$：$v<0$、$a<0$，同號，加速。$(2,3)$：$v<0$、$a>0$，減速。$(3,\\infty)$：$v>0$、$a>0$，加速。","速率增加的時段是 $(1,2)$ 與 $(3,\\infty)$。"],"answer":"$a(4)=12$；速率在 $(1,2)$、$(3,\\infty)$ 增加","note":"在 $(1,2)$ 裡 $a<0$，但質點正在加速：它往負方向跑得越來越快。"},{"title":"只給 $f'$","prompt":"$f'(x)=x^3-4x$。$f'$ 在哪些區間遞增？","steps":["$f''(x)=3x^2-4$。$f''=0$：$x^2=\\frac{4}{3}$，$x=\\pm\\frac{2}{\\sqrt{3}}\\approx\\pm 1.155$。","$3x^2-4$ 是開口向上的拋物線，在兩根之外為正、之間為負。","$f'$ 遞增：$(-\\infty,-\\frac{2}{\\sqrt{3}})$ 與 $(\\frac{2}{\\sqrt{3}},\\infty)$；遞減：$(-\\frac{2}{\\sqrt{3}},\\frac{2}{\\sqrt{3}})$。"],"answer":"$(-\\infty,-\\frac{2}{\\sqrt{3}})$ 與 $(\\frac{2}{\\sqrt{3}},\\infty)$"}],"pitfalls":["把 $f''>0$ 讀成「$f$ 遞增」。$f''>0$ 說的是 $f'$ 遞增，$f$ 本身可能正在下坡。","以為 $a<0$ 就是減速；要看 $v$ 和 $a$ 是否同號。","第二次微分時把第一次的結果抄錯，或乘法法則只做一半。","看 $f'$ 的圖找 $f''$ 的正負時，去看 $f'$ 在 $x$ 軸上方還是下方；要看的是 $f'$ 的圖往上還是往下走。"],"voice":"2dc7376b","sections":[{"title":"斜率怎麼變","beats":[{"show":["$f'$ 再微分一次：$f''$"],"note":"斜率每往右一單位，變化多少。","say":"f prime 是切線斜率。把它當成新的函數再微分一次，得到 f double prime：斜率變得多快。","t":[0,8808]},{"show":["$s(t)$ → $v=s'$ → $a=s''$"],"note":"位置 → 速度 → 加速度。","say":"最熟悉的例子是運動：位置微分是速度，速度再微分是加速度。","t":[8808,15336]},{"show":["加速度：速度變化得多快"],"say":"所以加速度不是跑多快，而是速度本身變化得多快。","t":[15336,20760]}],"predict":{"ask":"加速度 $a(t)=s''(t)$ 量的是？","options":[{"label":"速度變化得多快","correct":true},{"label":"跑得多快","why":"跑得多快是速度 $v=s'$，只微分一次。"},{"label":"位置在哪裡","why":"位置是 $s(t)$ 本身，一次都沒有微分。"}]}},{"title":"$f''$ 管 $f'$ 的增減","beats":[{"show":["$f''>0$：$f'$ 遞增","$f''<0$：$f'$ 遞減"],"note":"把〈增減區間〉用在 $f'$ 身上。","say":"上一課的規則換成用在 f prime 身上：f double prime 是正的，f prime 就遞增。","t":[20760,27672]},{"show":["斜率 $-2$、$-1$、$0$、$1$、$2$"],"note":"切線越來越往上翹，曲線像碗。","say":"f prime 遞增，就是切線一路往上翹：負二、負一、零、一、二，曲線像碗一樣往上彎。","t":[27672,36792]},{"show":["$f''$ 是 $f'$ 圖形的斜率"],"note":"$f'$ 的圖往上走的地方，$f''>0$。","say":"讀圖時，f double prime 是 f prime 那張圖的斜率。看的是它往上走還是往下走。","t":[36792,44832]}],"check":3},{"title":"算一次 $f''$","beats":[{"show":["$f(x)=xe^x$"],"note":"$f'(x)=(x+1)e^x$","say":"x 乘 e 的 x 次方。用乘法法則，f prime 是 x 加一乘 e 的 x 次方。","t":[44832,51864]},{"show":["$f''(x)=(x+2)e^x$"],"note":"再用一次乘法法則。","say":"再用一次乘法法則：e 的 x 次方加上 x 加一乘 e 的 x 次方，合起來是 x 加二乘 e 的 x 次方。","t":[51864,60432]},{"show":["$x>-2$：$f''>0$"],"note":"$e^x$ 恆正，正負跟 $x+2$ 一樣。","say":"e 的 x 次方永遠是正的，所以 x 大於負二時 f double prime 是正的。","t":[60432,66720]},{"show":["$f'$ 在 $(-2,\\infty)$ 遞增"],"note":"是 $f'$ 遞增，不是 $f$ 遞增。","say":"結論是 f prime 在負二以右遞增。小心，這說的是斜率在變大，f 本身可能還在下坡。","t":[66720,75624]}],"check":0},{"title":"加速還是減速","beats":[{"show":["加速：速率 $|v|$ 變大"],"note":"跟 $a$ 的正負不是同一件事。","say":"日常說的加速，是速率變大，也就是速度的絕對值變大，跟 a 是正是負不是一回事。","t":[75624,83736]},{"show":["$v=-5$，$a=-2$"],"note":"往負方向越來越快。","say":"速度負五、加速度負二：速度往負方向越來越大，其實速率在變大。","t":[83736,90912]},{"show":["$v$、$a$ 同號：速率增加","異號：速率減少"],"say":"規則是看 v 和 a 同不同號：同號，速率增加；異號，速率減少。","t":[90912,98016]},{"show":["$(v^2)'=2va$"],"note":"$va>0$ 時 $v^2$ 遞增。","say":"原因：v 平方的導數是二 v a。v a 是正的，v 平方就遞增，速率跟著變大。","t":[98016,106656]}],"check":1},{"title":"直線運動","beats":[{"show":["$s(t)=t^3-6t^2+9t$"],"note":"$v(t)=3(t-1)(t-3)$","say":"質點位置是 t 三次方減六 t 平方加九 t。微分一次是速度，分解成三倍的 t 減一乘 t 減三。","t":[106656,116424]},{"show":["$a(t)=6(t-2)$，$a(4)=12$"],"say":"再微分一次，加速度是六倍的 t 減二。t 等於四時，加速度是十二。","t":[116424,124272]},{"show":["$(0,1)$ 減速，$(1,2)$ 加速","$(2,3)$ 減速，$(3,\\infty)$ 加速"],"note":"$v$ 在 $1$、$3$ 換號，$a$ 在 $2$ 換號。","say":"v 在一和三換號，a 在二換號，切成四段比符號。同號的一到二、三以後，速率在增加。","t":[124272,134136]},{"show":["$(1,2)$：$a<0$ 也在加速"],"note":"往負方向跑得越來越快。","say":"注意一到二這段，加速度是負的，質點卻在加速，因為它往負方向越跑越快。","t":[134136,141912]}],"check":2},{"title":"記號與例外","beats":[{"show":["$f''(x)=y''=\\frac{d^2y}{dx^2}$"],"note":"把 $\\frac{d}{dx}$ 作用兩次。","say":"f double prime、y double prime、d 平方 y d x 平方，都是同一個東西：微分兩次。","t":[141912,149568]},{"show":["$f(x)=x|x|$：$f'(x)=2|x|$"],"note":"$f'$ 在 $0$ 有尖角，$f''(0)$ 不存在。","say":"f prime 存在，不保證 f double prime 存在。x 乘絕對值 x 的導數是二倍絕對值 x，在零是尖角。","t":[149568,159000]},{"show":["$f'(x)=x^3-4x$"],"note":"$f''(x)=3x^2-4$","say":"只給 f prime 也能問：f prime 是 x 三次方減四 x，再微分是三 x 平方減四。","t":[159000,166368]},{"show":["$f''=0$：$x=\\pm\\frac{2}{\\sqrt{3}}\\approx\\pm 1.155$"],"note":"開口向上的拋物線。","say":"等於零在正負二除以根號三，大約一點一五五。它是開口向上的拋物線。","t":[166368,174096]}],"predict":{"ask":"$f'(x)=x^3-4x$ 在哪裡遞增？","options":[{"label":"$(-\\infty,-\\frac{2}{\\sqrt{3}})$ 與 $(\\frac{2}{\\sqrt{3}},\\infty)$","correct":true},{"label":"$(-\\frac{2}{\\sqrt{3}},\\frac{2}{\\sqrt{3}})$","why":"開口向上的拋物線在兩根之間是負的，那段 $f''<0$，$f'$ 遞減。"},{"label":"全體實數","why":"$f''=3x^2-4$ 會變號；在 $x=0$ 是 $-4$，那附近 $f'$ 在遞減。"}]}}],"checks":[{"ask":"某一段區間上 $f'<0$、$f''>0$。這段的 $f$：","options":[{"label":"在下坡，但坡越來越緩","correct":true},{"label":"在上坡","why":"上坡要 $f'>0$。$f''>0$ 只說斜率在變大（例如 $-3$ 變 $-1$），斜率本身仍是負的。"},{"label":"在下坡，而且越來越陡","why":"越來越陡是斜率越來越負，那是 $f'$ 遞減，要 $f''<0$。"}]},{"ask":"某時刻 $v=-4$、$a=-3$。質點的速率：","options":[{"label":"正在增加","correct":true},{"label":"正在減少，因為 $a<0$","why":"$a$ 的正負只說速度往哪個方向變。$v$ 和 $a$ 都是負的，速度往負方向越來越大，速率在增加。"},{"label":"不變","why":"$a\\ne 0$，速度一定在變；$va=12>0$，所以 $v^2$ 在增加，速率也在增加。"}]},{"ask":"$s(t)=t^3-6t^2+9t$。$a(t)$ 是？","options":[{"label":"$6t-12$","correct":true},{"label":"$3t^2-12t+9$","why":"這是 $v(t)=s'(t)$。加速度要再微分一次。"},{"label":"$6t$","why":"$-12t$ 微分是 $-12$，漏掉了。"}]},{"ask":"圖上是 $f'$ 的圖形。$f''>0$ 的地方在哪？","options":[{"label":"$f'$ 的圖往上走的地方","correct":true},{"label":"$f'$ 的圖在 $x$ 軸上方的地方","why":"在 $x$ 軸上方是 $f'>0$，那說的是 $f$ 遞增。$f''$ 是 $f'$ 的斜率，要看 $f'$ 的圖往哪裡走。"},{"label":"$f'$ 的圖穿過 $x$ 軸的地方","why":"$f'$ 穿過 $x$ 軸是 $f$ 的臨界點，跟 $f''$ 的正負無關。"}]}],"practice":[{"id":"lec-02-q4a","core":true},{"id":"db-mot-002","core":true},{"id":"der-029","core":true},{"id":"dd-kin-004","core":true},{"id":"exam-der-007","core":true},{"id":"lec-02-q4d","core":true},{"id":"dd-kin-003"},{"id":"uni-der-005"},{"id":"gx-005","challenge":true,"note":"挑戰：圖上是 $f'=x^3-4x$；$f'$ 的山頂與谷底就是 $f''$ 換號的地方。"}]},"concavity":{"id":"concavity","prerequisites":["second-derivative","increasing-decreasing"],"next":["inflection-points"],"related":["mean-value-theorem","linear-approximation"],"objectives":["說出凹向上、凹向下的定義：$f'$ 在區間上遞增或遞減。","用 $f''$ 的正負求凹向上、凹向下的區間，定義域斷開處分段寫。","知道凹向上時曲線在切線上方，並用它判斷切線估計是高估還是低估。"],"concept":[{"heading":"① 碗口朝上、碗口朝下","body":["$y=x^2$ 像一個碗口朝上的碗，$y=-x^2$ 碗口朝下。差別在切線的斜率怎麼變：沿著 $x^2$ 往右走，斜率從負變到正、一路變大；沿著 $-x^2$ 走，斜率一路變小。","所以「彎的方向」可以用斜率的變化來描述，不需要靠眼睛看。這比「看起來像碗」精確，也能算：斜率的變化率就是上一課的 $f''$。"]},{"heading":"② 定義","body":["設 $f$ 在區間 $I$ 上可微。$f'$ 在 $I$ 上遞增，就說 $f$ 在 $I$ 上凹向上；$f'$ 在 $I$ 上遞減，就說 $f$ 在 $I$ 上凹向下。","注意凹性跟 $f$ 本身遞增或遞減無關：$x^2$ 在 $(-\\infty,0)$ 上是下坡，但整段都凹向上。","名詞提醒：有些書用「凸函數」「凹函數」，而且不同書的用法剛好相反。本課程只說凹向上、凹向下，不會混淆。"]},{"heading":"③ 用 $f''$ 判斷","body":["$f'$ 遞增或遞減，由 $f'$ 的導數 $f''$ 決定（〈增減區間〉用在 $f'$ 上）：在區間 $I$ 上 $f''>0$，$f$ 在 $I$ 上凹向上；$f''<0$，凹向下。","步驟跟找增減區間一樣，只是對象換成 $f''$：求 $f''$ 並因式分解 → 找 $f''=0$、$f''$ 不存在、以及不在定義域的點 → 切開數線 → 每段看 $f''$ 的正負。"]},{"heading":"④ 曲線與切線的位置","body":["凹向上的那一段，曲線在每一條切線的上方；凹向下時在下方。所以在凹向上的地方用切線估計函數值（〈線性近似〉），會低估；凹向下則會高估。"]},{"heading":"為什麼凹向上的曲線在切線上方","body":["設 $f$ 在 $I$ 上可微、$f'$ 在 $I$ 上遞增，$a\\in I$。要證：$I$ 裡每個 $x\\ne a$ 都有 $f(x)>f(a)+f'(a)(x-a)$。","$x>a$：由〈均值定理〉，有 $c\\in(a,x)$ 使 $f(x)-f(a)=f'(c)(x-a)$。$c>a$ 而 $f'$ 遞增，所以 $f'(c)>f'(a)$；乘上正數 $x-a$，得 $f(x)-f(a)>f'(a)(x-a)$。","$x<a$：同樣有 $c\\in(x,a)$ 使 $f(a)-f(x)=f'(c)(a-x)$。$c<a$，所以 $f'(c)<f'(a)$；乘上正數 $a-x$，得 $f(a)-f(x)<f'(a)(a-x)$，移項就是 $f(x)>f(a)+f'(a)(x-a)$。"],"collapsible":true}],"workedExamples":[{"title":"三次多項式","prompt":"求 $f(x)=x^3-3x^2$ 凹向上、凹向下的區間。","problemId":"gx-051","steps":["$f'(x)=3x^2-6x$，$f''(x)=6x-6=6(x-1)$。","$f''=0$ 在 $x=1$。$x<1$ 時 $f''<0$，$x>1$ 時 $f''>0$。","凹向下：$(-\\infty,1)$；凹向上：$(1,\\infty)$。"],"answer":"凹向下 $(-\\infty,1)$；凹向上 $(1,\\infty)$"},{"title":"先除再微分","prompt":"求 $f(x)=\\frac{x^2}{x-1}$ 凹向上、凹向下的區間。","problemId":"lec-04-q3d","steps":["長除法：$x^2=(x-1)(x+1)+1$，所以 $f(x)=x+1+\\frac{1}{x-1}$（$x\\ne 1$）。這樣微分比除法法則省事。","$f'(x)=1-\\frac{1}{(x-1)^2}$，$f''(x)=\\frac{2}{(x-1)^3}$。","$f''$ 沒有零點，只在不屬於定義域的 $x=1$ 換號：$x>1$ 時 $(x-1)^3>0$，$f''>0$；$x<1$ 時 $f''<0$。","凹向上：$(1,\\infty)$；凹向下：$(-\\infty,1)$。"],"answer":"凹向上 $(1,\\infty)$；凹向下 $(-\\infty,1)$"},{"title":"有一個恆正因式","prompt":"求 $f(x)=xe^{-x}$ 凹向上的區間。","problemId":"gx-052","steps":["$f'(x)=(1-x)e^{-x}$。","再用乘法法則：$f''(x)=-e^{-x}+(1-x)(-e^{-x})=(x-2)e^{-x}$。","$e^{-x}>0$，正負看 $x-2$：$x>2$ 時 $f''>0$。","凹向上：$(2,\\infty)$；凹向下：$(-\\infty,2)$。"],"answer":"$(2,\\infty)$"}],"pitfalls":["用 $f'$ 的正負判斷凹性。$f'$ 管上坡下坡，凹性要看 $f''$。","以為凹向上就是遞增：$x^2$ 在 $x<0$ 時凹向上，但在下坡。","$f''$ 換號的點只找 $f''=0$，漏掉定義域斷開的點（$\\frac{x^2}{x-1}$ 的 $x=1$）。","混用「凸函數／凹函數」，不同書定義相反；只說凹向上、凹向下。"],"figures":[{"caption":"切線在 x < 1 時在曲線上方，x > 1 時在下方","after":3,"widget":{"type":"family","f":"(a^3-3*a^2)+(3*a^2-6*a)*(x-a)","param":"a","range":[-0.5,3],"value":0.4,"window":[-1,3.5,-5,3],"extra":{"curves":[{"expr":"x^3-3*x^2","domain":[-1,1],"color":"violet","width":2.6},{"expr":"x^3-3*x^2","domain":[1,3.5],"color":"green","width":2.6}],"points":[{"x":1,"y":-2,"color":"ink"}],"labels":[{"x":-0.9,"y":2.3,"text":"凹向下","color":"violet"},{"x":2.05,"y":2.3,"text":"凹向上","color":"green"}]}}}],"voice":"1c076865","sections":[{"title":"碗口朝上、朝下","beats":[{"show":["$y=x^2$ 碗口朝上","$y=-x^2$ 碗口朝下"],"say":"x 平方像一個碗口朝上的碗，負 x 平方碗口朝下。差別在哪裡？","t":[0,7224]},{"show":["看斜率怎麼變"],"note":"沿著 $x^2$ 往右走，斜率從負變正。","say":"沿著 x 平方往右走，切線斜率從負的變到正的，一路變大；負 x 平方則一路變小。","t":[7224,15336]},{"show":["斜率的變化率就是 $f''$"],"note":"不用靠眼睛看，可以算。","say":"所以彎的方向不用靠眼睛看，用斜率怎麼變來描述，而斜率的變化率就是 f double prime。","t":[15336,23400]}],"predict":{"ask":"沿著 $y=-x^2$ 往右走，切線斜率：","options":[{"label":"一路變小","correct":true},{"label":"一路變大","why":"一路變大是碗口朝上的 $x^2$。$-x^2$ 的斜率 $-2x$ 從正變到負。"},{"label":"不變","why":"斜率不變的是直線；彎的曲線斜率一定在變。"}]}},{"title":"定義","beats":[{"show":["$f'$ 遞增：凹向上","$f'$ 遞減：凹向下"],"note":"$f$ 在區間 $I$ 上可微。","say":"定義很直接：在一段區間上，f prime 遞增就叫凹向上，f prime 遞減就叫凹向下。","t":[23400,31296]},{"show":["凹性 ≠ 遞增遞減"],"note":"$x^2$ 在 $(-\\infty,0)$ 是下坡，但凹向上。","say":"凹性跟 f 本身往上往下無關。x 平方在左半邊是下坡，可是整段都凹向上。","t":[31296,39624]},{"show":["只說凹向上、凹向下"],"note":"凸函數、凹函數的用法各書相反。","say":"有些書說凸函數、凹函數，而且不同書剛好相反。我們只說凹向上、凹向下，不會混淆。","t":[39624,49560]}],"check":1},{"title":"用 $f''$ 判斷","beats":[{"show":["$f''>0$：凹向上","$f''<0$：凹向下"],"say":"f prime 遞增還是遞減，看它的導數 f double prime：正的凹向上，負的凹向下。","t":[49560,56832]},{"show":["求 $f''$ → 切點 → 每段看正負"],"note":"跟找增減區間一樣，對象換成 $f''$。","say":"步驟跟找增減區間一樣：f double prime 因式分解，找零點、不存在和斷開的點，一段一段看。","t":[56832,65784]},{"show":["$f(x)=x^3-3x^2$"],"note":"$f''(x)=6x-6=6(x-1)$","say":"例如 x 三次方減三 x 平方。微分兩次得六 x 減六，也就是六倍的 x 減一。","t":[65784,73752]},{"show":["凹向下 $(-\\infty,1)$","凹向上 $(1,\\infty)$"],"say":"x 小於一時是負的，凹向下；大於一時是正的，凹向上。","t":[73752,79968]}],"check":0},{"title":"曲線與切線","beats":[{"show":["切點在 $x<1$：切線在曲線上方"],"fig":{"use":0,"to":0},"say":"看圖，同一條 x 三次方減三 x 平方。切點放在零，凹向下那段，切線在曲線的上方。","t":[79968,89376]},{"show":["切點在 $x>1$：切線在曲線下方"],"fig":{"use":0,"to":2},"say":"把切點移到二，到了凹向上那段，曲線整個在切線的上方。","t":[89376,95136]},{"show":["凹向上：切線低估","凹向下：切線高估"],"note":"見〈線性近似〉。","say":"所以用切線估函數值：凹向上的地方切線在下面，會低估；凹向下會高估。完整證明在全文。","t":[95136,105048]}],"check":2},{"title":"先除再微分","beats":[{"show":["$f(x)=\\frac{x^2}{x-1}=x+1+\\frac{1}{x-1}$"],"note":"長除法，比除法法則省事。","say":"x 平方除以 x 減一。先做長除法，寫成 x 加一，再加 x 減一分之一，微分比較省事。","t":[105048,114528]},{"show":["$f''(x)=\\frac{2}{(x-1)^3}$"],"say":"微分兩次，得到 x 減一的三次方分之二。","t":[114528,119040]},{"show":["$f''$ 沒有零點"],"note":"只在不屬於定義域的 $x=1$ 換號。","say":"分子是二，永遠不是零。可是 x 等於一不在定義域裡，正負會在那裡換。","t":[119040,126984]}],"predict":{"ask":"$f(x)=\\frac{x^2}{x-1}$ 在哪裡凹向上？","options":[{"label":"$(1,\\infty)$","correct":true},{"label":"$(-\\infty,1)$","why":"$x<1$ 時 $(x-1)^3<0$，$f''<0$，那段是凹向下。"},{"label":"沒有，因為 $f''$ 沒有零點","why":"你只找了 $f''=0$；不在定義域的 $x=1$ 也是換號的地方。"}]}},{"title":"恆正的因式","beats":[{"show":["$f(x)=xe^{-x}$"],"note":"$f'(x)=(1-x)e^{-x}$","say":"x 乘 e 的負 x 次方。f prime 是一減 x，乘 e 的負 x 次方。","t":[126984,133416]},{"show":["$f''(x)=(x-2)e^{-x}$"],"note":"再用一次乘法法則。","say":"再用一次乘法法則，整理成 x 減二，乘 e 的負 x 次方。","t":[133416,139200]},{"show":["凹向上 $(2,\\infty)$"],"note":"$e^{-x}>0$，正負看 $x-2$。","say":"e 的負 x 次方永遠是正的，正負只看 x 減二，所以二以右凹向上。","t":[139200,145968]}],"check":3}],"checks":[{"ask":"$f''(x)=12x^2-12$。$f$ 在哪裡凹向下？","options":[{"label":"$(-1,1)$","correct":true},{"label":"$(-\\infty,-1)$ 與 $(1,\\infty)$","why":"這兩段 $12x^2-12>0$，那是凹向上。代 $x=0$：$f''=-12<0$，凹向下在中間。"},{"label":"$(-\\infty,0)$","why":"你可能看的是 $f'$ 或 $f''$ 的某一個因式。$f''=12(x-1)(x+1)$，零點在 $\\pm 1$。"}]},{"ask":"$f$ 在某區間上凹向上。下面哪一個一定成立？","options":[{"label":"$f'$ 在這個區間上遞增","correct":true},{"label":"$f$ 在這個區間上遞增","why":"凹性管的是 $f'$ 的增減，不是 $f$ 的增減。$x^2$ 在 $(-\\infty,0)$ 上凹向上，卻是遞減。"},{"label":"$f'>0$","why":"$f'$ 可以是負的、只是越來越大，例如 $x^2$ 在 $x<0$ 時 $f'=2x<0$。"}]},{"ask":"$f$ 在 $a$ 附近凹向下。用 $a$ 點的切線估計 $f(a+0.1)$，結果：","options":[{"label":"高估","correct":true},{"label":"低估","why":"凹向下時曲線在切線下方，切線的值比真正的函數值大，是高估。低估是凹向上的情形。"},{"label":"剛好相等","why":"只有在切點本身相等；離開切點，曲線就跟切線分開了。"}]},{"ask":"$f(x)=\\sin x$，$0<x<2\\pi$。$f$ 在哪裡凹向上？","options":[{"label":"$(\\pi,2\\pi)$","correct":true},{"label":"$(0,\\pi)$","why":"$f''=-\\sin x$。在 $(0,\\pi)$ 上 $\\sin x>0$，$f''<0$，是凹向下。"},{"label":"$(\\frac{\\pi}{2},\\frac{3\\pi}{2})$","why":"那是 $f'=\\cos x<0$ 的地方，說的是 $f$ 遞減，不是凹性。"}]}],"practice":[{"id":"gx-051","core":true},{"id":"lec-04-q3d","core":true},{"id":"gx-052","core":true},{"id":"gx-053","core":true},{"id":"gx-054","core":true},{"id":"ig-num-009","challenge":true,"note":"挑戰：梯形法用的是割線；凹向上時割線在曲線上方，所以高估。跟切線（低估）方向相反。"}]},"inflection-points":{"id":"inflection-points","prerequisites":["concavity"],"next":["second-derivative-test"],"related":["first-derivative-test","increasing-decreasing"],"objectives":["說出反曲點的定義：$f$ 在該點連續，而且凹性在那裡改變。","列出候選點（$f''=0$ 或 $f''$ 不存在），再逐一檢查 $f''$ 有沒有換號。","知道 $f''(c)=0$ 既不保證是反曲點，反曲點也不一定有 $f''(c)=0$。"],"concept":[{"heading":"① 彎的方向換邊的地方","body":["$x^3-3x^2$ 在 $x=1$ 左邊凹向下、右邊凹向上。曲線在這一點從「碗口朝下」換成「碗口朝上」，這種點叫反曲點。","定義：$f$ 在 $c$ 連續，而且在 $c$ 的一側凹向上、另一側凹向下，就說點 $(c,f(c))$ 是 $f$ 的反曲點。反曲點是圖形上的一個點，答案可以寫座標，題目只問位置時寫 $x=c$。"]},{"heading":"② 候選點：$f''=0$ 或 $f''$ 不存在","body":["凹性由 $f''$ 的正負決定，所以凹性只可能在 $f''$ 換號的地方改變，跟〈增減區間〉找切點的道理一樣。候選點是定義域裡 $f''=0$ 或 $f''$ 不存在的點。","然後每個候選點都要檢查：$f''$ 在兩側有沒有換號。換號才是反曲點。"]},{"heading":"③ $f''(c)=0$ 不夠，也不必要","body":["不夠：$f(x)=x^4$，$f''(x)=12x^2$，$f''(0)=0$。但 $12x^2$ 在 $0$ 兩側都是正的，整條曲線都凹向上，$0$ 不是反曲點。","不必要：$f(x)=\\sqrt[3]{x}$，$f''(x)=-\\frac{2}{9}x^{-5/3}$，在 $0$ 不存在。$x<0$ 時 $f''>0$、$x>0$ 時 $f''<0$，凹性換了，而 $\\sqrt[3]{x}$ 在 $0$ 連續，所以原點是反曲點。","還有一種：凹性換了，但那一點不在定義域裡。$\\frac{x^2}{x-1}$ 在 $x=1$ 兩側凹性不同，可是 $f(1)$ 沒有定義，所以沒有反曲點。"]},{"heading":"$f''$ 連續時，反曲點一定有 $f''(c)=0$","body":["設 $f''$ 在 $c$ 附近存在且在 $c$ 連續，而 $(c,f(c))$ 是反曲點。假如 $f''(c)>0$，由連續性，$c$ 附近一小段 $(c-\\delta,c+\\delta)$ 上都有 $f''>0$，那 $f$ 在 $c$ 的兩側都凹向上，凹性沒有改變，矛盾。$f''(c)<0$ 同理。所以 $f''(c)=0$。","這個結論需要「$f''$ 在 $c$ 存在且連續」；$\\sqrt[3]{x}$ 不符合這個條件，所以不衝突。"],"collapsible":true}],"workedExamples":[{"title":"偶次多項式","prompt":"求 $f(x)=x^4-6x^2$ 的反曲點。","problemId":"si-set-017","steps":["$f'(x)=4x^3-12x$，$f''(x)=12x^2-12=12(x-1)(x+1)$。","候選點：$x=-1$、$x=1$（$f''$ 處處存在）。","$x<-1$：$f''>0$。$-1<x<1$：$f''<0$。$x>1$：$f''>0$。兩個候選點都換號。","$f(\\pm 1)=1-6=-5$。反曲點是 $(-1,-5)$ 與 $(1,-5)$。"],"answer":"$(-1,-5)$、$(1,-5)$"},{"title":"只給 $f'$","prompt":"某函數的導函數是 $f'(x)=(x+2)(x-1)^2$。求 $f$ 所有反曲點的 $x$ 座標。","problemId":"lec-04-q4c","steps":["對 $f'$ 用乘法法則：$f''(x)=(x-1)^2+(x+2)\\cdot 2(x-1)$。","提出 $(x-1)$：$f''(x)=(x-1)((x-1)+2(x+2))=(x-1)(3x+3)=3(x-1)(x+1)$。","$f''$ 在 $x=-1$、$x=1$ 都是一次因式的零點，兩側換號。","反曲點在 $x=-1$ 與 $x=1$。"],"answer":"$x=-1$、$x=1$","note":"$x=1$ 同時是臨界點（$f'(1)=0$）和反曲點：切線水平，曲線穿過切線，所以不是極值。"},{"title":"$f''$ 不存在的反曲點","prompt":"$f(x)=\\sqrt[3]{x}=x^{1/3}$。原點是不是反曲點？","steps":["$x\\ne 0$ 時：$f'(x)=\\frac{1}{3}x^{-2/3}$，$f''(x)=-\\frac{2}{9}x^{-5/3}$。在 $x=0$ 這兩個式子都沒有意義，$f''(0)$ 不存在。","$x>0$：$x^{-5/3}>0$，$f''<0$，凹向下。$x<0$：$x^{-5/3}=\\frac{1}{(\\sqrt[3]{x})^5}<0$，$f''>0$，凹向上。","$\\sqrt[3]{x}$ 在 $0$ 連續，凹性在 $0$ 改變，所以原點 $(0,0)$ 是反曲點。"],"answer":"是，原點是反曲點"}],"pitfalls":["解出 $f''=0$ 就宣布是反曲點，沒有檢查換號（$x^4$ 的 $0$）。","只找 $f''=0$，漏掉 $f''$ 不存在的點（$\\sqrt[3]{x}$ 的 $0$）。","把不在定義域的點也算成反曲點（$\\frac{x^2}{x-1}$ 的 $1$）。","把 $f'=0$ 的點當成反曲點候選；那是極值的候選。"],"voice":"36c1e1d1","sections":[{"title":"彎的方向換邊","beats":[{"show":["$x^3-3x^2$ 在 $x=1$"],"note":"左邊凹向下、右邊凹向上。","say":"x 三次方減三 x 平方，在一的左邊凹向下，右邊凹向上。曲線在這裡換了彎的方向。","t":[0,9144]},{"show":["反曲點：凹性換邊的點"],"note":"$f$ 在 $c$ 連續，一側凹向上、另一側凹向下。","say":"這種點叫反曲點：f 在 c 連續，而且 c 的一邊凹向上、另一邊凹向下。","t":[9144,16344]},{"show":["答案是點 $(c,f(c))$"],"note":"只問位置時寫 $x=c$。","say":"反曲點是圖形上的一個點，可以寫座標；題目只問位置，寫 x 等於 c 就好。","t":[16344,23736]}],"predict":{"ask":"$f(x)=x^3-3x^2$ 的反曲點是？","options":[{"label":"$(1,-2)$","correct":true},{"label":"$(2,-4)$","why":"$x=2$ 是 $f'=3x^2-6x=0$ 的解，是臨界點；凹性換邊在 $f''=6(x-1)$ 的零點。"},{"label":"$(0,0)$","why":"$x=0$ 也是 $f'=0$ 的點，那是極值的候選，不是凹性換邊的地方。"}]}},{"title":"候選點與檢查","beats":[{"show":["候選：$f''=0$ 或 $f''$ 不存在"],"note":"凹性只可能在 $f''$ 換號的地方改變。","say":"凹性由 f double prime 的正負決定，所以只可能在它等於零或不存在的地方改變。","t":[23736,30816]},{"show":["每個候選都要檢查換號"],"say":"候選只是候選，每一個都要看兩側有沒有換號，換號才是反曲點。","t":[30816,37464]},{"show":["$f(x)=x^4-6x^2$"],"note":"$f''(x)=12(x-1)(x+1)$","say":"例如 x 四次方減六 x 平方。微分兩次分解成十二倍的 x 減一乘 x 加一。","t":[37464,45144]},{"show":["$+$、$-$、$+$：兩個都換號"],"note":"$f(\\pm 1)=1-6=-5$","say":"符號是正、負、正，負一和一都換號。代回去高度都是負五。","t":[45144,52488]},{"show":["反曲點 $(-1,-5)$、$(1,-5)$"],"say":"所以兩個反曲點是負一、負五，和一、負五。","t":[52488,57528]}],"check":1},{"title":"$f''=0$ 不夠","beats":[{"show":["$f(x)=x^4$：$f''(0)=0$"],"note":"$f''(x)=12x^2$","say":"x 四次方微分兩次是十二 x 平方，在零等於零。那零是反曲點嗎？","t":[57528,65112]},{"show":["$12x^2$ 兩側都是正的"],"note":"整條曲線凹向上，凹性沒換。","say":"十二 x 平方在零的兩邊都是正的，整條曲線都凹向上，所以零不是反曲點。","t":[65112,72744]},{"show":["$f'=0$ 是極值的候選"],"note":"不是反曲點的候選。","say":"也別把 f prime 等於零的點拿來當候選，那是找極值用的。","t":[72744,78360]}],"check":0},{"title":"證明：反過來假設","proof":true,"of":3,"skeleton":"反證","beats":[{"show":["反證：假設 $f''(c)\\ne0$"],"note":"$f''$ 在 $c$ 連續，$(c,f(c))$ 是反曲點。","say":"策略：反證。假設 f double prime 在 c 不是零，推出凹性沒有換邊，跟反曲點矛盾。","t":[78360,87048]},{"show":["假如 $f''(c)>0$：","$(c-\\delta,c+\\delta)$ 上都有 $f''>0$"],"note":"$f''$ 在 $c$ 連續，正號帶到附近一小段。","why":{"ask":"為什麼附近一整段都 $f''>0$？","say":"只知道 c 這一點是正的，為什麼附近一整段也是正的？","options":[{"label":"$f''$ 在 $c$ 連續","correct":true},{"label":"$f''(c)>0$ 就代表附近都凹向上","why":"只在一點為正不夠；要 $f''$ 連續，才能把正號帶到附近一整段。"},{"label":"$f'$ 在 $c$ 可微","why":"那只保證 $f''(c)$ 存在，不保證附近的 $f''$ 跟它同號；要的是連續。"}],"t":[87048,92376]},"say":"f double prime 在 c 連續，而且是正的，所以 c 附近一小段裡，f double prime 都還是正的。","t":[92376,100416]},{"show":["$c$ 兩側都凹向上：凹性沒換邊"],"note":"反曲點要凹性在 $c$ 換邊，矛盾。","why":{"ask":"矛盾在哪裡？","say":"兩側都凹向上。這跟什麼矛盾？","options":[{"label":"反曲點要求凹性在 $c$ 換邊","correct":true},{"label":"$f''(c)$ 應該等於 $0$","why":"那是要證的結論，不能拿來當矛盾的另一邊。"},{"label":"$f$ 在 $c$ 不連續","why":"$f$ 可微，當然連續；矛盾出在凹性沒有換邊。"}],"t":[100416,104712]},"say":"左右兩側都凹向上，凹性根本沒換。可是反曲點的定義就是凹性在 c 換邊，矛盾。","t":[104712,113640]},{"show":["$f''(c)<0$ 同理 ⇒ $f''(c)=0$"],"say":"小於零也一樣，兩側都凹向下。兩種都不行，只剩 f double prime 在 c 等於零。","t":[113640,121824]}],"where":{"ask":"「$f''$ 在 $c$ 連續」用在哪一步？","steps":[{"label":"假設 $f''(c)>0$","why":"這只是反證的假設。"},{"label":"附近一整段 $f''>0$","correct":true},{"label":"兩側都凹向上，矛盾","why":"這只用到「$f''>0$ 就凹向上」和反曲點的定義。"}]}},{"title":"只給 $f'$","beats":[{"show":["$f'(x)=(x+2)(x-1)^2$"],"say":"這次只給 f prime：x 加二，乘 x 減一的平方。反曲點在哪？","t":[121824,128592]},{"show":["$f''(x)=(x-1)^2+(x+2)\\cdot 2(x-1)$"],"note":"對 $f'$ 用乘法法則。","say":"對 f prime 用乘法法則，兩項都有 x 減一，可以提出來。","t":[128592,134328]},{"show":["$f''(x)=3(x-1)(x+1)$"],"note":"兩個都是一次因式，兩側換號。","say":"整理成三倍的 x 減一乘 x 加一。兩個都是一次因式，所以負一和一都換號，都是反曲點。","t":[134328,143520]},{"show":["$x=1$：臨界點，也是反曲點"],"note":"切線水平，曲線穿過切線，不是極值。","say":"一同時是臨界點和反曲點：切線是水平的，但曲線穿過切線，所以不是極值。","t":[143520,151608]}],"check":2},{"title":"$f''$ 不存在也行","beats":[{"show":["$f(x)=\\sqrt[3]{x}$"],"note":"$f''(x)=-\\frac{2}{9}x^{-5/3}$，$f''(0)$ 不存在。","say":"三次方根 x 微分兩次，是負九分之二乘 x 的負三分之五次方，在零不存在。","t":[151608,159216]},{"show":["$x<0$：凹向上","$x>0$：凹向下"],"say":"x 是負的，f double prime 是正的，凹向上；x 是正的，凹向下。凹性換了。","t":[159216,167592]},{"show":["原點 $(0,0)$ 是反曲點"],"note":"$\\sqrt[3]{x}$ 在 $0$ 連續。","say":"而三次方根 x 在零連續，所以原點是反曲點。f double prime 等於零，並不是必要的。","t":[167592,176400]},{"show":["$\\frac{x^2}{x-1}$ 在 $x=1$：沒有"],"note":"凹性換了，但 $f(1)$ 沒有定義。","say":"反過來，x 平方除以 x 減一在一的兩側凹性不同，可是那一點不在圖形上，不是反曲點。","t":[176400,185064]}],"check":3}],"checks":[{"ask":"$f(x)=x^4$。$x=0$ 是不是反曲點？","options":[{"label":"不是，$f''=12x^2$ 在 $0$ 兩側都是正的","correct":true},{"label":"是，因為 $f''(0)=0$","why":"$f''(0)=0$ 只是候選。$12x^2$ 在 $0$ 兩側都正，整條曲線凹向上，凹性沒換。"},{"label":"是，因為 $f'(0)=0$","why":"$f'(0)=0$ 說的是切線水平，那是極值的候選，跟凹性無關。$x^4$ 在 $0$ 是極小值。"}]},{"ask":"$f(x)=x^3-6x^2+5$。反曲點的 $x$ 座標是？","options":[{"label":"$2$","correct":true},{"label":"$0$ 與 $4$","why":"那是 $f'=3x^2-12x=0$ 的解，是臨界點。反曲點要解 $f''=6x-12$。"},{"label":"$6$","why":"$f''=6x-12=0$ 解出來是 $x=2$，不是 $6$。"}]},{"ask":"$f''(x)=(x-3)^2(x+1)$。$f$ 的反曲點在？","options":[{"label":"只有 $x=-1$","correct":true},{"label":"$x=3$ 與 $x=-1$","why":"$(x-3)^2$ 在 $3$ 兩側都正，$f''$ 在 $3$ 不換號，凹性沒變。"},{"label":"只有 $x=3$","why":"重根不換號；真正換號的是一次因式 $x+1$。"}]},{"ask":"$f$ 在 $x=1$ 沒有定義，$f''$ 在 $1$ 的兩側一正一負。$f$ 在 $x=1$ 有反曲點嗎？","options":[{"label":"沒有，反曲點要在圖形上、$f$ 要在那點連續","correct":true},{"label":"有，因為凹性換了","why":"凹性換了還不夠；$f(1)$ 沒有定義，圖形上根本沒有這一點。$\\frac{x^2}{x-1}$ 就是這種情形。"},{"label":"要看 $f''(1)$ 是不是 $0$","why":"$f$ 在 $1$ 沒定義，$f''(1)$ 也不存在；問題出在那一點不在定義域。"}]}],"practice":[{"id":"cx-curve-001","core":true},{"id":"si-set-019","core":true},{"id":"gi-002","core":true},{"id":"si-set-017","core":true},{"id":"cx-curve-002","core":true},{"id":"si-set-018","core":true},{"id":"lec-04-q4c","core":true},{"id":"cx-curve-008"},{"id":"gi-006"},{"id":"gi-007"},{"id":"gi-008"},{"id":"cx-curve-007"},{"id":"gx-005"},{"id":"db-ext-011","challenge":true,"note":"挑戰：$x^2e^{-x}$ 的 $f''=(x^2-4x+2)e^{-x}$，要解二次方程。"},{"id":"dx-bio-002","challenge":true,"note":"挑戰：成長最快的時刻就是 $P'$ 最大、$P$ 的反曲點。"}]},"second-derivative-test":{"id":"second-derivative-test","prerequisites":["first-derivative-test","concavity"],"next":["asymptotes"],"related":[],"objectives":["在 $f'(c)=0$ 的點，用 $f''(c)$ 的正負判斷局部極大或極小。","知道 $f''(c)=0$ 時這個判別不給結論，要改用〈一階導數判別〉。","會挑方法：$f''$ 好算就用二階，不好算或判別失效就用一階。"],"concept":[{"heading":"① 平的切線＋碗口方向","body":["在 $f'(c)=0$ 的點，切線是水平的。如果那附近凹向上（碗口朝上），水平切線就落在碗底，$f(c)$ 是局部極小；凹向下（碗口朝下），水平切線在頂上，$f(c)$ 是局部極大。","這是直覺，不是證明：它用「$f''(c)>0$」代表「$c$ 附近凹向上」，但 $f''$ 只在一點為正，並不直接告訴我們一整段的凹性。嚴格的論證在下面的可折疊區塊，不需要這個假設。"]},{"heading":"② 判別法","body":["設 $f'(c)=0$，而且 $f''(c)$ 存在。","$f''(c)>0$：$f(c)$ 是局部極小。","$f''(c)<0$：$f(c)$ 是局部極大。","$f''(c)=0$：判別法不給結論。"],"tex":["f'(c)=0,\\ f''(c)>0\\ \\Rightarrow\\ \\text{局部極小};\\qquad f'(c)=0,\\ f''(c)<0\\ \\Rightarrow\\ \\text{局部極大}"]},{"heading":"③ $f''(c)=0$ 時，什麼都可能","body":["三個函數在 $0$ 都有 $f'(0)=0$、$f''(0)=0$：$x^4$ 在 $0$ 是局部極小，$-x^4$ 是局部極大，$x^3$ 不是極值。同樣的 $f''(0)=0$，三種結果都有，所以這時判別法不能下結論，要回去看 $f'$ 在兩側的正負。","另外，$f'(c)$ 不存在的臨界點（尖角）也不能用二階判別，因為 $f''(c)$ 根本不存在。"]},{"heading":"④ 一階還是二階？","body":["二階判別的好處是只要代一個數：算出 $f''(c)$ 看正負就好，不用畫整張符號表。適合 $f''$ 好算、臨界點不多的時候。","一階判別比較耐用：$f''(c)=0$、$f'(c)$ 不存在、$f''$ 很難算時都能用。而且它順便給出整段的增減，畫圖時本來就需要。所以習慣是：先試二階，判不出來就回到一階。"]},{"heading":"證明（$f''(c)>0$ 的情形）","body":["$f''(c)$ 存在，表示 $f'$ 在 $c$ 附近存在，所以 $f$ 在 $c$ 附近可微、在 $c$ 連續。","由導數定義與 $f'(c)=0$：$f''(c)=\\lim_{x\\to c}\\frac{f'(x)-f'(c)}{x-c}=\\lim_{x\\to c}\\frac{f'(x)}{x-c}>0$。","極限是正數，所以存在 $\\delta>0$，使 $0<|x-c|<\\delta$ 時 $\\frac{f'(x)}{x-c}>0$。也就是：$x\\in(c-\\delta,c)$ 時 $x-c<0$，所以 $f'(x)<0$；$x\\in(c,c+\\delta)$ 時 $f'(x)>0$。","$f'$ 在 $c$ 由負變正，由〈一階導數判別〉，$f(c)$ 是局部極小。$f''(c)<0$ 的情形同理。"],"collapsible":true}],"workedExamples":[{"title":"兩個臨界點都判得出來","prompt":"$f(x)=x^3-3x$。用二階導數判別找局部極值。","problemId":"gi-001","steps":["$f'(x)=3x^2-3=3(x-1)(x+1)$，臨界點 $x=-1$、$x=1$。$f''(x)=6x$。","$f''(-1)=-6<0$：局部極大，$f(-1)=-1+3=2$。","$f''(1)=6>0$：局部極小，$f(1)=1-3=-2$。"],"answer":"局部極大 $f(-1)=2$；局部極小 $f(1)=-2$"},{"title":"判別失效，改用一階","prompt":"$f(x)=x^4-4x^3$。判斷兩個臨界點。","problemId":"db-ext-012","steps":["$f'(x)=4x^2(x-3)$，臨界點 $x=0$、$x=3$。$f''(x)=12x^2-24x$。","$f''(3)=108-72=36>0$：局部極小，$f(3)=81-108=-27$。","$f''(0)=0$：二階判別沒有結論。","改看 $f'$ 的正負（〈一階導數判別〉）：$4x^2$ 不換號，$x-3$ 在 $0$ 附近是負的，所以 $f'$ 在 $0$ 兩側都負，$x=0$ 不是極值。"],"answer":"局部極小 $f(3)=-27$；$x=0$ 不是極值"},{"title":"指數函數","prompt":"$f(x)=xe^{-x}$。找局部極值。","problemId":"gi-004","steps":["$f'(x)=(1-x)e^{-x}$，$e^{-x}$ 不為 $0$，臨界點只有 $x=1$。","$f''(x)=(x-2)e^{-x}$（〈凹向上／凹向下〉範例 3 算過）。$f''(1)=-e^{-1}<0$。","局部極大，$f(1)=1\\cdot e^{-1}=\\frac{1}{e}\\approx 0.368$。"],"answer":"局部極大 $f(1)=\\frac{1}{e}$"}],"pitfalls":["$f''(c)=0$ 時下結論說「不是極值」。$x^4$ 就是反例。","符號記反：$f''>0$ 是極小（碗口朝上），不是極大。","對 $f'$ 不存在的臨界點用二階判別。","判出極大極小之後忘了代回 $f$ 求極值本身。"],"voice":"0ec38474","sections":[{"title":"平的切線＋碗口","beats":[{"show":["$f'(c)=0$：切線水平"],"say":"在 f prime 等於零的點，切線是水平的。接下來只要看碗口朝哪邊。","t":[0,7200]},{"show":["凹向上：碗底，局部極小"],"say":"附近凹向上，碗口朝上，水平切線就落在碗底，f 在 c 是局部極小。","t":[7200,14400]},{"show":["凹向下：頂上，局部極大"],"say":"凹向下，碗口朝下，水平切線在頂上，那是局部極大。","t":[14400,20448]},{"show":["直覺，不是證明"],"note":"$f''$ 只在一點為正，不直接給整段的凹性。","say":"這是直覺：f double prime 只在一點是正的，不代表附近一整段都凹向上。證明在後面那節。","t":[20448,29736]}],"predict":{"ask":"$f'(c)=0$，而且 $c$ 附近碗口朝下。$f(c)$ 是？","options":[{"label":"局部極大","correct":true},{"label":"局部極小","why":"碗口朝下時，水平切線在頂上，是山頂不是谷底。"},{"label":"不是極值","why":"切線水平、兩邊都往下彎，$f(c)$ 比附近都高，是極值。"}]}},{"title":"判別法","beats":[{"show":["$f'(c)=0$，$f''(c)>0$：極小","$f'(c)=0$，$f''(c)<0$：極大"],"note":"$f''(c)=0$：不給結論。","say":"判別法：f prime 在 c 是零，再看 f double prime 在 c 的值。正的是極小，負的是極大，零就不下結論。","t":[29736,39720]},{"show":["$f(x)=x^3-3x$"],"note":"臨界點 $-1$、$1$；$f''(x)=6x$。","say":"例如 x 三次方減三 x。臨界點是負一和一，二階導數是六 x。","t":[39720,46944]},{"show":["$f''(-1)=-6<0$：極大 $f(-1)=2$"],"say":"負一代進去得負六，是負的，局部極大，高度二。","t":[46944,52320]},{"show":["$f''(1)=6>0$：極小 $f(1)=-2$"],"say":"一代進去得六，是正的，局部極小，高度負二。只要代一個數就判斷完了。","t":[52320,60576]}],"check":0},{"title":"證明：$f'$ 由負變正","proof":true,"of":4,"skeleton":"ε-δ","beats":[{"show":["把 $f''(c)>0$ 變成 $f'$ 兩側的正負號"],"note":"最後交給〈一階導數判別〉。","say":"策略：f double prime 在 c 只是一點的資訊。用導數定義把它變成 f prime 在 c 兩側的正負號。","t":[60576,69408]},{"show":["$f''(c)=\\lim_{x\\to c}\\frac{f'(x)}{x-c}>0$"],"note":"導數定義，分子的 $f'(c)=0$。","say":"f double prime 在 c 就是 f prime 的差商的極限；f prime c 是零，分子只剩 f prime x。","t":[69408,76896]},{"show":["$0<|x-c|<\\delta$ 時 $\\frac{f'(x)}{x-c}>0$"],"note":"極限是正數，夠近時比值也是正的。","why":{"ask":"為什麼附近的比值都是正的？","say":"只知道極限是正的。為什麼 c 附近的比值也都是正的？","options":[{"label":"比值的極限是正數","correct":true},{"label":"$f''$ 在 $c$ 附近都是正的","why":"這裡沒假設 $f''$ 在附近存在或連續；正號是從極限的定義來的。"},{"label":"$x-c$ 一定是正的","why":"$x$ 可以在 $c$ 左邊，那時 $x-c<0$；下一步就要用到這件事。"}],"t":[76896,82920]},"say":"極限是正數，x 離 c 夠近時，比值離極限夠近，也就還是正的。這就是那個 delta。","t":[82920,91704]},{"show":["左邊 $x-c<0$ ⇒ $f'(x)<0$","右邊 $x-c>0$ ⇒ $f'(x)>0$"],"note":"比值為正，分子分母同號。","why":{"ask":"為什麼左邊 $f'(x)<0$？","say":"c 的左邊，f prime x 為什麼是負的？","options":[{"label":"比值 $>0$，分母 $x-c<0$","correct":true},{"label":"$c$ 是極小，左邊是下坡","why":"$c$ 是極小正是要證的；這裡是從比值的正負號推出來的。"},{"label":"$f''>0$，所以 $f'$ 遞增","why":"沒假設 $f''$ 在附近都是正的；只用到比值 $>0$。"}],"t":[91704,95688]},"say":"比值是正的，左邊的分母 x 減 c 是負的，分子 f prime x 只好也是負的；右邊兩個都是正的。","t":[95688,104544]},{"show":["$f'$ 由負變正 ⇒ $f(c)$ 是局部極小"],"note":"$f$ 在 $c$ 可微，所以連續。","say":"f prime 在 c 由負變正，一階導數判別說 f 在 c 是局部極小。小於零的情形同理。","t":[104544,113040]}],"where":{"ask":"「$f'(c)=0$」用在哪一步？","steps":[{"label":"$f''(c)=\\lim_{x\\to c}\\frac{f'(x)}{x-c}$","correct":true},{"label":"附近的比值都 $>0$","why":"這只用到極限是正數。"},{"label":"左邊 $f'<0$、右邊 $f'>0$","why":"這只用到比值為正、分子分母同號。"},{"label":"由一階導數判別得局部極小","why":"這只用到 $f'$ 由負變正，以及 $f$ 在 $c$ 連續。"}]}},{"title":"$f''(c)=0$ 時","beats":[{"show":["$x^4$、$-x^4$、$x^3$"],"note":"在 $0$ 都有 $f'(0)=0$、$f''(0)=0$。","say":"看三個函數：x 四次方、負 x 四次方、x 三次方。在零的一階、二階導數全都是零。","t":[113040,122544]},{"show":["極小、極大、不是極值"],"say":"可是 x 四次方在零是極小，負 x 四次方是極大，x 三次方根本不是極值。","t":[122544,129984]},{"show":["回去看 $f'$ 兩側的正負"],"note":"也就是〈一階導數判別〉。","say":"同樣是零，三種結果都有，所以判別法不能下結論，要回去看 f prime 在兩側的正負。","t":[129984,138240]}],"check":1},{"title":"判別失效","beats":[{"show":["$f(x)=x^4-4x^3$"],"note":"$f'(x)=4x^2(x-3)$，臨界點 $0$、$3$。","say":"x 四次方減四 x 三次方。導數是四 x 平方乘 x 減三，臨界點零和三。","t":[138240,146256]},{"show":["$f''(x)=12x^2-24x$"],"say":"二階導數是十二 x 平方減二十四 x。","t":[146256,150552]},{"show":["$f''(3)=36>0$：極小 $f(3)=-27$"],"say":"三代進去是三十六，正的，局部極小，高度負二十七。","t":[150552,156696]},{"show":["$f''(0)=0$：沒有結論"],"note":"改看 $f'$：$4x^2$ 不換號，看 $x-3$。","say":"零代進去是零，判別法沒結論，改用一階：四 x 平方不換號，正負看 x 減三。","t":[156696,164880]}],"predict":{"ask":"$x=0$ 是？","options":[{"label":"不是極值","correct":true},{"label":"局部極小","why":"你可能想到 $x^4$；但這裡 $x-3$ 在 $0$ 附近是負的，$f'$ 在 $0$ 兩側都負，沒有換號。"},{"label":"局部極大","why":"左邊 $f'$ 也是負的，$f$ 是一路下坡經過 $0$，不是先上後下。"}]}},{"title":"指數函數","beats":[{"show":["$f(x)=xe^{-x}$"],"note":"$f'(x)=(1-x)e^{-x}$，臨界點只有 $x=1$。","say":"x 乘 e 的負 x 次方。導數是一減 x 乘 e 的負 x 次方，指數那項不會是零，臨界點只有一。","t":[164880,174168]},{"show":["$f''(1)=-e^{-1}<0$"],"note":"$f''(x)=(x-2)e^{-x}$","say":"二階導數是 x 減二乘 e 的負 x 次方。代一進去是負的 e 分之一，小於零。","t":[174168,182112]},{"show":["局部極大 $f(1)=\\frac{1}{e}\\approx 0.368$"],"say":"所以是局部極大。別忘了代回 f，極大值是 e 分之一，大約零點三六八。","t":[182112,189936]}],"check":2},{"title":"一階還是二階","beats":[{"show":["二階：只要代一個數"],"note":"$f''$ 好算、臨界點不多時好用。","say":"二階判別的好處是只要代一個數，不用畫整張符號表。","t":[189936,195312]},{"show":["尖角不能用二階"],"note":"$f'(c)$ 不存在，$f''(c)$ 也不存在。","say":"可是 f prime 不存在的尖角，f double prime 更不存在，二階判別用不上。","t":[195312,201912]},{"show":["一階比較耐用"],"note":"還順便給出整段的增減。","say":"一階判別什麼情況都能用，還順便告訴你整段的增減。習慣是先試二階，判不出來就回到一階。","t":[201912,211920]}],"check":3}],"checks":[{"ask":"$f'(2)=0$、$f''(2)=-5$。$x=2$ 是？","options":[{"label":"局部極大","correct":true},{"label":"局部極小","why":"$f''<0$ 是凹向下、碗口朝下，水平切線在頂上，是極大。"},{"label":"無法判斷","why":"只有 $f''(c)=0$ 才無法判斷；$f''(2)=-5\\ne 0$，判別法有結論。"}]},{"ask":"$f'(0)=0$、$f''(0)=0$。關於 $x=0$：","options":[{"label":"二階判別沒有結論，要看 $f'$ 在兩側的正負","correct":true},{"label":"一定不是極值","why":"$x^4$ 在 $0$ 也是 $f'=f''=0$，卻是局部極小。"},{"label":"一定是反曲點","why":"$f''(0)=0$ 只是反曲點的候選；$x^4$ 在 $0$ 凹性沒換，不是反曲點。"}]},{"ask":"$f(x)=x^2\\ln x$（$x>0$）的臨界點是 $x=e^{-1/2}$。$f''(x)=2\\ln x+3$。這一點是？","options":[{"label":"局部極小","correct":true},{"label":"局部極大","why":"代進去：$f''(e^{-1/2})=2\\cdot(-\\frac{1}{2})+3=2>0$，是極小。"},{"label":"無法判斷，因為 $\\ln$ 是負的","why":"$\\ln(e^{-1/2})=-\\frac{1}{2}$ 是負的沒關係，要看的是整個 $f''=2\\ln x+3=2>0$。"}]},{"ask":"$f(x)=|x|$ 在 $0$ 有極小值。能用二階導數判別嗎？","options":[{"label":"不能，$f'(0)$ 與 $f''(0)$ 都不存在","correct":true},{"label":"能，$f''(0)=0$ 所以無法判斷","why":"$|x|$ 在 $0$ 是尖角，$f'(0)$ 就不存在，更談不上 $f''(0)$。要用一階導數判別。"},{"label":"能，$f''(x)=0$ 對 $x\\ne 0$ 成立","why":"判別法要的是 $c$ 這一點本身的 $f'(c)=0$ 與 $f''(c)$；兩者在 $0$ 都不存在。"}]}],"practice":[{"id":"gi-001","core":true},{"id":"gi-004","core":true},{"id":"gi-003","core":true},{"id":"db-ext-005","core":true},{"id":"db-ext-012","core":true},{"id":"gx-026"},{"id":"gx-027"},{"id":"gx-029"},{"id":"db-ext-013","challenge":true,"note":"挑戰：二階判別只說 $x=1$ 是局部極大；要說它是整條數線上的最大值，還要看 $x\\to\\pm\\infty$ 時 $f\\to 0$。"}]}});
